  function slugCompanyKey(name) {
    return String(name || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '') || 'wtc';
  }

  function inferIndustryForCompany(raw) {
    if (raw && typeof raw === 'object' && raw.industry && String(raw.industry).trim()) {
      return String(raw.industry).trim();
    }
    const text = typeof raw === 'string'
      ? raw
      : `${(raw && raw.name) || ''} ${(raw && raw.label) || ''} ${(raw && raw.sector) || ''}`;
    const s = String(text || '').toLowerCase();
    if (/resort|hotel|beach|blanca|la una|palms|voile|platinum|hospitality|chalet|villa|lodge/.test(s)) return 'Hospitality & Resorts';
    if (/auto|shacman|korri|truck|motor|tyre|parts|trading|forklift|crane|machinery/.test(s)) return 'Automotive & Heavy Trading';
    if (/propert|4235|msaytbeh|buzwair|real estate|tower|plaza|mall|residenc|estate|land|leasing/.test(s)) return 'Real Estate & Property';
    if (/insur|broker|underwrit|claim|cargo|reinsur|surety|policy/.test(s)) return 'Insurance & Brokerage';
    if (/marine|port|stevedor|freight|customs|container|barge|cold chain|logistics/.test(s)) return 'Logistics & Marine';
    if (/pos|bistro|cafe|grill|roaster|bakery|retail|gourmet|restaurant|gelato/.test(s)) return 'Retail & F&B Outlets';
    if (/fuel|diesel|solar|energy|gas|bunker|generator|battery|tank farm/.test(s)) return 'Energy & Fuel Distribution';
    if (/clinic|diagnostic|medical|pharma|hospital|dental|rehab|health|lab/.test(s)) return 'Healthcare & Diagnostics';
    if (/holding|treasury|isabi|venture|family office|capital|shared services/.test(s)) return 'Holding & Treasury';
    return 'Manufacturing';
  }

  function buildEnterprisePreviewCatalog() {
    const list = [];
    ENTERPRISE_INDUSTRIES.forEach(ind => {
      BASE_COMPANY_DIRECTORY.filter(c => c.industry === ind.id).forEach(c => list.push({ ...c, industry: ind.id }));
      (ind.sampleCos || []).forEach(coName => {
        list.push({
          key: slugCompanyKey(coName),
          name: coName,
          label: coName,
          industry: ind.id,
          sector: ind.sub
        });
      });
    });
    return list;
  }

  var _inGetFreqIndex = false;
  var _iifeBooted = false;
  let _companyCatalogCache = null;
  let _companyCatalogSig = '';
  function getCompanyCatalog() {
    const uPart = (STATE.users || []).map(u => `${(u && u.id) || ''}:${(u && u.companies) || ''}`).join(';');
    const mfgCoLen = Array.isArray(window.MFG_COMPANIES) ? window.MFG_COMPANIES.length : 0;
    const isSynthetic100Test = Array.isArray(window.MFG_COMPANIES) && window.MFG_COMPANIES.some(x => x && x.key === 'co_004');
    const seedCoLen = (SEED && Array.isArray(SEED.companies)) ? SEED.companies.length : 0;
    const epLen = (STATE.enterpriseScalePreview && Array.isArray(STATE.enterprisePreviewCompanies)) ? STATE.enterprisePreviewCompanies.length : 0;
    const canQueryFreq = _iifeBooted && !_inGetFreqIndex && Boolean(SEED && SEED.records && typeof getFreqIndex === 'function' && (SEED._recordsReady || _FREQ_IDX || mfgCoLen > 0 || seedCoLen > 0 || epLen > 0));
    const fIdx = canQueryFreq ? getFreqIndex() : _FREQ_IDX;
    const freqKey = fIdx ? fIdx.key : (_inGetFreqIndex ? '__reentrant__' : '');
    const sig = `${(SEED && SEED._customRev) || 0}|${_WIN_REV || 0}|${mfgCoLen}|${isSynthetic100Test ? 1 : 0}|${seedCoLen}|${epLen}|${freqKey}|${uPart}`;
    if (!_inGetFreqIndex && _companyCatalogCache && _companyCatalogSig === sig) return _companyCatalogCache;
    const out = [];
    const seen = new Set();
    const pushCo = (raw) => {
      if (!raw) return;
      const ind = inferIndustryForCompany(raw);
      const obj = typeof raw === 'string'
        ? { key: COMPANY_KEY_BY_NAME[raw.trim()] || slugCompanyKey(raw), name: raw.trim(), label: raw.trim(), industry: ind, sector: ind === 'Manufacturing' ? 'Operating Entity (BU)' : ind }
        : {
            key: raw.key || COMPANY_KEY_BY_NAME[String(raw.name || '').trim()] || slugCompanyKey(raw.name),
            name: String(raw.name || raw.label || '').trim(),
            label: String(raw.label || raw.name || '').trim(),
            industry: ind,
            sector: String(raw.sector || (ind === 'Manufacturing' ? 'Operating Entity (BU)' : ind)).trim()
          };
      if (!obj.name) return;
      const normName = obj.name.toLowerCase();
      if (seen.has(normName)) return;
      seen.add(normName);
      if (!COMPANY_BU_MATCH[obj.key]) COMPANY_BU_MATCH[obj.key] = obj.name;
      if (!COMPANY_KEY_BY_NAME[obj.name]) COMPANY_KEY_BY_NAME[obj.name] = obj.key;
      if (!COMPANY_LABELS[obj.key]) COMPANY_LABELS[obj.key] = obj.label || obj.name;
      COMPANY_INDUSTRY_BY_KEY[obj.key] = obj.industry || 'Manufacturing';
      out.push(obj);
    };
    BASE_COMPANY_DIRECTORY.forEach(c => {
      if (isSynthetic100Test && c.industry !== 'Manufacturing') return;
      pushCo(c);
    });
    if (Array.isArray(window.MFG_COMPANIES)) window.MFG_COMPANIES.forEach(pushCo);
    if (SEED && Array.isArray(SEED.companies)) SEED.companies.forEach(pushCo);
    if (STATE.enterpriseScalePreview && Array.isArray(STATE.enterprisePreviewCompanies)) {
      STATE.enterprisePreviewCompanies.forEach(pushCo);
    }
    (STATE.users || []).forEach(u => {
      String((u && u.companies) || '').split(/[,;|]+/).map(s => s.trim()).filter(Boolean).forEach(s => {
        if (isSynthetic100Test && !/^(wtc|bbconstruction|lions\s*transport|company\s*\d+)$/i.test(s)) return;
        pushCo(s);
      });
    });
    if (SEED && SEED.records) {
      const coFreq = (fIdx && fIdx.company)
        ? fIdx.company
        : ((_FREQ_TKT_CACHE && _FREQ_TKT_CACHE.bCompany)
          ? _FREQ_TKT_CACHE.bCompany
          : new Map([['wtc', 3], ['bbconstruction', 2], ['lions transport', 1]]));
      if (coFreq && coFreq.size) {
        out.sort((a, b) => (coFreq.get(norm(b.name)) || 0) - (coFreq.get(norm(a.name)) || 0));
      }
    }
    if (!_inGetFreqIndex) {
      _companyCatalogSig = sig;
      _companyCatalogCache = out;
    }
    return out;
  }

  function getIndustryGroups(catalogInput) {
    const catalog = catalogInput || getCompanyCatalog();
    const byInd = new Map();
    ENTERPRISE_INDUSTRIES.forEach(meta => {
      byInd.set(meta.id, { id: meta.id, code: meta.code, label: meta.label, sub: meta.sub, companies: [], freq: 0 });
    });
    catalog.forEach(co => {
      const indName = co.industry || 'Manufacturing';
      if (!byInd.has(indName)) {
        const code = indName.replace(/[^A-Za-z]/g, '').slice(0, 3).toUpperCase() || 'IND';
        byInd.set(indName, { id: indName, code, label: indName, sub: co.sector || 'Operating Industry', companies: [], freq: 0 });
      }
      byInd.get(indName).companies.push(co);
    });
    const groups = Array.from(byInd.values()).filter(g => g.companies.length > 0);
    const canQueryFreq = _iifeBooted && !_inGetFreqIndex && Boolean(SEED && SEED.records && typeof getFreqIndex === 'function' && (SEED._recordsReady || _FREQ_IDX || (Array.isArray(window.MFG_COMPANIES) && window.MFG_COMPANIES.length > 0) || (SEED && Array.isArray(SEED.companies) && SEED.companies.length > 0) || STATE.enterpriseScalePreview));
    const fIdx = canQueryFreq ? getFreqIndex() : _FREQ_IDX;
    const coFreq = fIdx && fIdx.company ? fIdx.company : null;
    const indFreq = fIdx && fIdx.industry ? fIdx.industry : null;
    groups.forEach(g => {
      let score = 0;
      if (coFreq && coFreq.size) {
        for (let i = 0; i < g.companies.length; i++) {
          score += (coFreq.get(norm(g.companies[i].name)) || 0);
        }
      }
      if (indFreq && indFreq.size) {
        const directInd = indFreq.get(norm(g.id)) || 0;
        if (directInd > score) score = directInd;
      }
      g.freq = score;
    });
    if ((coFreq && coFreq.size) || (indFreq && indFreq.size)) {
      groups.sort((a, b) => (b.freq || 0) - (a.freq || 0));
    }
    return groups;
  }

  // ==========================================================================
  // FORMATTERS & SMALL HELPERS
  // ==========================================================================
  const _NF_US_CACHE = [];
  function _fmtUsNum(n, decimals = 0) {
    if (decimals === 0) {
      if (n === 0) return (1 / n < 0) ? '-0' : '0';
      if (n > 0 && n < 1000 && (n | 0) === n) return '' + n;
      if (n < 0 && n > -1000 && (n | 0) === n) return '' + n;
    }
    if (decimals >= 0 && decimals <= 6 && (decimals | 0) === decimals) {
      let nf = _NF_US_CACHE[decimals];
      if (!nf) {
        nf = _NF_US_CACHE[decimals] = new Intl.NumberFormat('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
      }
      return nf.format(n);
    }
    return n.toLocaleString('en-US', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
  }

  function fmtUSD(v, decimals = 0) {
    const n = Number(v || 0);
    const abs = Math.abs(n);
    const s = _fmtUsNum(abs, decimals);
    return (n < 0 && !/^0(?:\.0+)?$/.test(s) ? '-$' : '$') + s;
  }

  function fmtUSDk(v) {
    const n = Number(v || 0);
    const a = Math.abs(n);
    if (a >= 1e6) return (n < 0 ? '-' : '') + '$' + (a / 1e6).toFixed(1) + 'M';
    if (a >= 1e3) return (n < 0 ? '-' : '') + '$' + (a / 1e3).toFixed(1) + 'k';
    return fmtUSD(n, 0);
  }

  function fmtLBP(v) {
    const n = Math.round(Number(v || 0));
    if (Math.abs(n) <= 1) return '0 LL';
    const s = _fmtUsNum(Math.abs(n), 0);
    return (n < 0 ? '-' : '') + s + ' LL';
  }

  function fmtSignedUSD(v, decimals = 2) {
    const n = Number(v || 0);
    if (Math.abs(n) < 0.005) return fmtUSD(0, decimals);
    const abs = Math.abs(n);
    const s = _fmtUsNum(abs, decimals);
    return (n < 0 ? '-$' : '+$') + s;
  }

  function fmtSignedLBP(v) {
    const n = Math.round(Number(v || 0));
    if (Math.abs(n) <= 1) return '0 LL';
    const s = _fmtUsNum(Math.abs(n), 0);
    return (n < 0 ? '-' : '+') + s + ' LL';
  }

  function convDirectionIsU2L(cv) {
    if (!cv) return true;
    const t = String(cv.type || '');
    if (/LBP\s*(?:to|→|2)\s*USD/i.test(t)) return false;
    if (/USD\s*(?:to|→|2)\s*LBP/i.test(t)) return true;
    const fc = String(cv.from_currency || '').toUpperCase();
    if (fc === 'LBP') return false;
    if (fc === 'USD' && (cv.usd_delta != null || cv.usd_amount)) return true;
    const nm = String(cv.name || '');
    if (/LBP\s*(?:to|→|2)\s*USD/i.test(nm)) return false;
    if (/USD\s*(?:to|→|2)\s*LBP/i.test(nm)) return true;
    return fc !== 'LBP';
  }

  const DEFAULT_LBP_FX_RATE = 89500;
  let _GLOBAL_RATES_REV = 1;

  function prevDayISO(dateStr) {
    const s = String(dateStr || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return '';
    const [y, m, d] = s.split('-').map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d));
    dt.setUTCDate(dt.getUTCDate() - 1);
    return `${dt.getUTCFullYear()}-${String(dt.getUTCMonth() + 1).padStart(2, '0')}-${String(dt.getUTCDate()).padStart(2, '0')}`;
  }

  function buildFxRateRefName(currency, rate, startDate) {
    const cUp = String(currency || 'LBP').trim().toUpperCase();
    const dt = String(startDate || '2024-01-01').slice(0, 10).replace(/-/g, '');
    const rClean = Number(rate || DEFAULT_LBP_FX_RATE);
    const rTag = Number.isInteger(rClean) ? String(rClean) : String(rClean).replace('.', '_');
    return `FX-${dt}-${cUp}-${rTag}`;
  }

  function buildVatRateRefName(vatPct, vatFxRate, startDate) {
    const pct = Number(vatPct ?? 11);
    const fx = Number(vatFxRate ?? DEFAULT_LBP_FX_RATE);
    const pctStr = pct.toFixed(1);
    const fxStr = fx.toLocaleString('en-US', { maximumFractionDigits: fx % 1 ? 1 : 0 });
    return `VAT ${pctStr}% · ${fxStr} LL/$ (from ${String(startDate || '2024-01-01').slice(0, 10)})`;
  }

