  function getHubExceptionBadge(hubId, u, k, sentinelsOpen) {
    if (hubId === 'sentinels') return getSentinelExceptionBadge(u, sentinelsOpen);
    if (hubId === 'raw') return getPendingRawPriceExceptionBadge(u);
    if (hubId === 'expenses') return getPendingPriceExceptionBadge(u);
    if (hubId === 'fleet') return getFleetExceptionBadge(u) || getDieselExceptionBadge(u);
    if (hubId === 'payroll') return getPendingSalaryExceptionBadge(u) || getWorkforceMapExceptionBadge(u);
    if (hubId === 'ledger') return getLedgerExceptionBadge(u, k);
    if (hubId === 'hld_interactions') return getHoldingOpenReconExceptionBadge(u);
    if (hubId === 'hsp_memberships') return getHospitalityMembershipExceptionBadge(u);
    if (hubId === 'hsp_stock') return getHospitalityStockExceptionBadge(u);
    if (hubId === 'trd_purchases') return getTradingImportsExceptionBadge(u);
    if (hubId === 'trd_trucks') return getTradingTrucksExceptionBadge(u);
    if (hubId === 'trd_stock') return getTradingStockExceptionBadge(u);
    if (hubId === 're_leases') return getRealEstateLeasesExceptionBadge(u);
    if (hubId === 're_sales') return getRealEstateSalesExceptionBadge(u);
    if (hubId === 're_properties') return getRealEstatePortfolioExceptionBadge(u);
    if (hubId === 're_workorders') return getRealEstateWorkOrdersExceptionBadge(u);
    if (hubId === 'ins_policies') return getInsurancePoliciesExceptionBadge(u);
    if (hubId === 'ins_billing') return getInsuranceBillingExceptionBadge(u);
    if (hubId === 'ins_claims') return getInsuranceClaimsExceptionBadge(u);
    if (hubId === 'ins_catalogue') return getInsuranceCatalogueExceptionBadge(u);
    return null;
  }

