    loans.forEach(l => { if (l) inc(counterparty, l.lender || l.counterparty || l.name, 3); });
    extMovs.forEach(x => { if (x) inc(counterparty, x.counterparty || x.name, 3); });
    overs.forEach(o => { if (o) inc(region, o.region, 2); });
    (rec.sites || []).forEach(s => { if (s && s.region) inc(region, s.region, 1); });

    const item = new Map();
    const warehouseLoc = new Map([['wtc main warehouse', 40], ['bbconstruction spare store', 30], ['lions garage store', 20], ['crusher site store', 10]]);
    const supCategory = _cloneMap(_FREQ_TKT_CACHE.bSupCategory);
    const company = _cloneMap(_FREQ_TKT_CACHE.bCompany);

    expItems.forEach(r => {
      if (!r || r.voided) return;
      inc(item, r.item_name, 2);
      inc(warehouseLoc, r.warehouse_location, 1);
    });
    whMovs.forEach(r => {
      if (!r || r.voided) return;
      inc(item, r.item_name, 2);
      inc(warehouseLoc, r.location, 2);
    });
    repItems.forEach(r => {
      if (!r || r.voided) return;
      inc(item, r.item_name, 2);
    });
    oilLogs.forEach(r => {
      if (!r || r.voided) return;
      inc(item, r.oil_type, 2);
    });
    (rec.fuel_malfunctions || []).forEach(r => {
      if (!r || r.voided) return;
      const itNm = String(r.item || 'Diesel').trim();
      if (itNm) {
        inc(productFuel, itNm, 2);
        inc(item, itNm, 2);
      }
      if (r.equipment) inc(truck, r.equipment, 1);
      if (r.driver) inc(driver, r.driver, 1);
      if (r.warehouse_location) inc(warehouseLoc, r.warehouse_location, 1);
    });
    partMovs.forEach(r => {
      if (!r || r.voided) return;
      inc(item, r.part_name, 2);
      inc(warehouseLoc, r.storage_location, 2);
    });
    eqDefs.forEach(r => {
      if (!r || r.voided) return;
      inc(item, r.part_name, 1);
    });
