    const sumNetPeriod = filteredLeases.reduce((a, r) => a + r.net_period_usd, 0);
    const sumTtcPeriod = filteredLeases.reduce((a, r) => a + r.ttc_period_usd, 0);
    const sumAnnualTtc = filteredLeases.reduce((a, r) => a + r.annual_ttc_usd, 0);
