  function buildIndustryDomainTableRegister(ind, tabKey) {
    const pageMap = {
      'hld_entities_tbl': 0,
      'hld_open_ic_tbl': 1,
      'hld_pairs_tbl': 'hld_pairs_custom',
      'hld_partners_tbl': 2,
      'hld_loans_tbl': 3,
      'hsp_rev_tbl': 0,
      'hsp_memb_tbl': 2,
      'hsp_tariffs_tbl': 'hsp_tariffs_custom',
      'hsp_stock_tbl': 3,
      'hsp_gen_tbl': 4,
      'trd_inv_tbl': 0,
      'trd_tgt_tbl': 'trd_tgt_custom',
      'trd_imp_tbl': 2,
      'trd_vin_tbl': 3,
      'trd_wh_tbl': 4,
      're_leases_tbl': 1,
      're_prop_tbl': 0,
      're_sales_tbl': 2,
      're_wo_tbl': 4,
      'ins_pol_tbl': 0,
      'ins_ren_tbl': 2,
      'ins_stm_tbl': 'ins_stm_custom',
      'ins_clm_tbl': 4
    };
    const mapped = pageMap[tabKey];
    if (mapped === 'hsp_tariffs_custom') {
      const hsp = computeHospitalityOperations({ ignoreSearch: true });
      const trfs = hsp.tariffRows || [];
      const sumSes = round2(trfs.reduce((a, r) => a + Number(r.seasonal_rate_usd || 0), 0));
      const sumNgt = round2(trfs.reduce((a, r) => a + Number(r.nightly_rate_usd || 0), 0));
      return {
        tableTitle: 'Chronological Seasonal Chalet & Cabana Tariff Schedules Register',
        headers: ['Tariff ID', 'Resort', 'Tier / Unit Scope', 'Effective From', 'Effective To', 'Seasonal Rate ($)', 'Nightly Rate ($)', 'Status'],
        rows: trfs.map(r => [r.id, r.company, r.tier, r.start_date, r.end_date || 'Open', fmtUSD(r.seasonal_rate_usd, 0), fmtUSD(r.nightly_rate_usd, 0), r.status]),
        totals: [`${trfs.length} Tariffs`, `${hsp.activeResorts.length} Resorts`, 'All Tiers', 'Chronological', '0 Overlaps', fmtUSD(sumSes, 0), fmtUSD(sumNgt, 0), 'Active']
      };
    }
    if (mapped === 'trd_tgt_custom') {
      const trd = computeTradingOperations({ ignoreSearch: true });
      const tgts = trd.targetRows || [];
      const sumTgt = round2(tgts.reduce((a, r) => a + Number(r.target_ttc || 0), 0));
      const sumAct = round2(tgts.reduce((a, r) => a + Number(r.actual_ttc || 0), 0));
      return {
        tableTitle: 'Chronological Showroom Price Lists, Import Tariffs & Monthly Sales Targets Register',
        headers: ['Schedule ID', 'Entity', 'Category / Segment', 'Effective From', 'Effective To', 'Unit Net ($)', 'Target ($)', 'Actual Sales ($)'],
        rows: tgts.map(r => [r.id, r.company, r.category || r.segment, r.start_date || `${r.month}-01`, r.end_date || 'Open', fmtUSD(r.unit_net_usd || r.list_floor_usd || 0, 0), fmtUSD(r.target_ttc, 0), fmtUSD(r.actual_ttc, 0)]),
        totals: [`${tgts.length} Schedules`, 'Shacman + Korri Auto', 'All Categories', 'Chronological', '0 Overlaps', 'Active List', fmtUSD(sumTgt, 0), fmtUSD(sumAct, 0)]
      };
    }
    if (mapped === 'hld_pairs_custom') {
      const ic = computeIntercompanyInteractions({ ignoreSearch: true });
      const bil = ic.byBilateral || [];
      return {
        tableTitle: 'Bilateral Sister Due From / Due To Corridor Matrix',
        headers: ['Sister Corridor', 'Primary Lender', 'Primary Borrower', 'Given ($)', 'Paid Back ($)', 'Repaid %', 'Net Unpaid ($)'],
        rows: bil.map(b => [String(b.corridorLabel || '').replace(/[↔→]/g, ' / '), b.lender || '-', b.borrower || '-', fmtUSD(b.givenUsd, 2), fmtUSD(b.paidBackUsd, 2), `${Number(b.repayPct || 0).toFixed(1)}%`, fmtUSD(b.netUnpaidUsd, 2)]),
        totals: ['Total Bilateral Matrix', `${bil.length} Corridors`, `${ic.unpaidCorridorCount || 0} Open`, fmtUSD(ic.totalGivenUsd, 2), fmtUSD(ic.totalPaidBackUsd, 2), `${Number(ic.overallRepayPct || 0).toFixed(1)}%`, fmtUSD(ic.totalNetUnpaidUsd, 2)]
      };
    }
    if (mapped === 'ins_stm_custom') {
      const ins = computeInsuranceOperations();
      const st = ins.statements || [];
      const sumExp = round2(st.reduce((a, r) => a + Number(r.expected_comm_4117_usd || 0), 0));
      const sumStmt = round2(st.reduce((a, r) => a + Number(r.statement_comm_usd || 0), 0));
      const sumVar = round2(st.reduce((a, r) => a + Number(r.variance_usd || 0), 0));
      return {
        tableTitle: 'Carrier Monthly Commission Bordereau & Statement Reconciliation Register',
        headers: ['Statement ID', 'Period', 'Insurance Carrier', 'Policies', 'Expected Comm ($)', 'Statement Comm ($)', 'Variance ($)', 'Status'],
        rows: st.map(r => [r.id, r.period, r.carrier, fmtNum(r.policies_count), fmtUSD(r.expected_comm_4117_usd, 0), fmtUSD(r.statement_comm_usd, 0), fmtUSD(r.variance_usd, 0), r.status]),
        totals: [`${st.length} Statements`, '2026-10', '6 Carriers', fmtNum(st.reduce((a, r) => a + Number(r.policies_count || 0), 0)), fmtUSD(sumExp, 0), fmtUSD(sumStmt, 0), fmtUSD(sumVar, 0), `${ins.summary.stmtDiscrepancyCount} Discrepancies`]
      };
    }
    return buildIndustryDomainDataset(ind, typeof mapped === 'number' ? mapped : 0);
  }

  function renderIndustryDomainTablesExplorer(indOverride) {
    const ind = indOverride || getActiveIndustry(STATE.company);
    const tableTabsByInd = {
      'Holding & Treasury': [
        { key: 'hld_entities_tbl', label: '14-Entity Group Scorecard', view: 'hld_entities', newView: 'hld_interactions' },
        { key: 'hld_open_ic_tbl', label: 'Intercompany Repayment Ledger', view: 'hld_open_recon', newView: 'hld_interactions' },
        { key: 'hld_pairs_tbl', label: 'Sister Pair Matrix', view: 'hld_due_matrix', newView: 'hld_interactions' },
        { key: 'hld_partners_tbl', label: 'Partner Splits & Agreements', view: 'hld_partners', newView: 'hld_partners' },
        { key: 'hld_loans_tbl', label: 'Facility Rate Schedules', view: 'hld_loans', newView: 'hld_loans' }
      ],
      'Hospitality & Resorts': [
        { key: 'hsp_rev_tbl', label: 'Venue Revenue & Chalet Closes', view: 'hsp_revenue', newView: 'hsp_revenue' },
        { key: 'hsp_memb_tbl', label: 'Seasonal Memberships & Arrears', view: 'hsp_memberships', newView: 'hsp_memberships' },
        { key: 'hsp_tariffs_tbl', label: 'Seasonal Tariff Schedules', view: 'hsp_memberships', newView: 'hsp_tariffs' },
        { key: 'hsp_stock_tbl', label: 'Cellar, Kitchen & Recipe BOM', view: 'hsp_stock', newView: 'hsp_stock' },
        { key: 'hsp_gen_tbl', label: 'Generators, Diesel & Solar Logs', view: 'hsp_energy', newView: 'hsp_energy' }
      ],
      'Automotive & Heavy Trading': [
        { key: 'trd_inv_tbl', label: 'Sales Invoices & Books', view: 'trd_sales', newView: 'trd_sales' },
        { key: 'trd_tgt_tbl', label: 'Price Lists & Tariffs', view: 'trd_targets', newView: 'trd_targets' },
        { key: 'trd_imp_tbl', label: 'Imports & Landed Cost', view: 'trd_purchases', newView: 'trd_purchases' },
        { key: 'trd_vin_tbl', label: 'Showroom Serial Units (VINs)', view: 'trd_trucks', newView: 'trd_trucks' },
        { key: 'trd_wh_tbl', label: '5-Warehouse Spare Parts', view: 'trd_stock', newView: 'trd_stock' }
      ],
      'Real Estate & Property': [
        { key: 're_leases_tbl', label: 'Active Leases & Rent Roll', view: 're_leases', newView: 're_leases' },
        { key: 're_prop_tbl', label: 'Properties & /2400 Mulk Shares', view: 're_properties', newView: 're_leases' },
        { key: 're_sales_tbl', label: 'Property Sales & Instalments', view: 're_sales', newView: 're_sales' },
        { key: 're_wo_tbl', label: 'Fit-Out Work Orders & Recharges', view: 're_workorders', newView: 're_workorders' }
      ],
      'Insurance & Brokerage': [
        { key: 'ins_pol_tbl', label: 'Live Policies & Discounts', view: 'ins_policies', newView: 'ins_policies' },
        { key: 'ins_ren_tbl', label: '30/60/90-Day Renewal Queue', view: 'ins_renewals', newView: 'ins_policies' },
        { key: 'ins_stm_tbl', label: 'Carrier Statement Recon', view: 'ins_statements', newView: 'ins_agreements' },
        { key: 'ins_clm_tbl', label: 'Claims & Recovery Register', view: 'ins_claims', newView: 'ins_claims' }
      ]
    };
    const tabs = tableTabsByInd[ind] || tableTabsByInd['Holding & Treasury'];
    if (!STATE.indActiveDomainTable) STATE.indActiveDomainTable = {};
    const activeKey = STATE.indActiveDomainTable[ind] || tabs[0].key;
    const activeTabIdx = Math.max(0, tabs.findIndex(t => t.key === activeKey));
    const activeTab = tabs[activeTabIdx] || tabs[0];
    STATE.indActiveDomainTable[ind] = activeTab.key;

    const ds = buildIndustryDomainTableRegister(ind, activeTab.key);
    const allRows = ds.rows || [];
    const headers = ds.headers || [];
    const q = norm(STATE.indTablesSearch || '');
    const filteredRows = q
      ? allRows.filter(r => r.some(c => norm(c).includes(q)))
      : allRows;
    if (!STATE.indTablesSort) STATE.indTablesSort = {};
    const sortSpec = STATE.indTablesSort[activeTab.key] || { col: -1, dir: 'desc' };
    const sortedRows = sortIndMatrixRows(filteredRows, sortSpec.col, sortSpec.dir);
    const dynTotals = computeDynamicDomainTotals(headers, sortedRows, ds.totals, allRows.length);

    return `
      <div class="panel-card" id="industryDomainTablesExplorer" data-ind-tbl-active="${esc(activeTab.key)}" style="margin-bottom:14px;padding:12px 16px">
        <div class="panel-head" style="flex-wrap:wrap;gap:8px;margin-bottom:10px">
          <div>
            <div class="panel-title"><span>${ic('tables')} ${esc(ind.toUpperCase())} · DOMAIN RELATIONAL TABLES EXPLORER (${tabs.length} CORE REGISTERS)</span></div>
            <div style="font-size:11.5px;color:var(--muted);margin-top:2px">${esc(ds.tableTitle || activeTab.label)} · ${fmtNum(sortedRows.length)} of ${fmtNum(allRows.length)} records</div>
          </div>
          <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">
            <input type="search" id="indTablesSearchInput" class="search-input" style="height:30px;min-width:190px;font-size:11.5px" value="${esc(STATE.indTablesSearch || '')}" placeholder="Filter ${esc(activeTab.label)}...">
            ${(q || sortSpec.col >= 0) ? '<button type="button" class="btn btn-ghost-bar" style="padding:4px 9px;font-size:11px" id="indTablesResetBtn">Reset</button>' : ''}
            <button type="button" class="btn btn-primary" style="padding:4px 10px;font-size:11px" data-ind-open-new="${esc(activeTab.newView || activeTab.view)}">+ New Record</button>
            <button type="button" class="btn btn-ghost-bar" style="padding:4px 10px;font-size:11px" data-nav-jump="${esc(activeTab.view)}">Open Hub</button>
            ${exportBtn('industryDomainTablesExplorer', activeTab.key)}
          </div>
        </div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px" role="tablist" aria-label="Domain relational registers">
          ${tabs.map(t => `
            <button type="button" class="btn ${t.key === activeTab.key ? 'btn-primary' : 'btn-ghost-bar'}" style="padding:4px 10px;font-size:11px" data-ind-tbl-key="${esc(t.key)}">
              ${esc(t.label)}
            </button>
          `).join('')}
        </div>
        <div class="table-wrap">
          <table class="data-table" data-ind-table-title="${esc(ds.tableTitle || activeTab.label)}">
            <thead>
              <tr>${headers.map((h, hIdx) => {
                const isSorted = sortSpec.col === hIdx;
                const arrow = isSorted ? (sortSpec.dir === 'asc' ? ' ▲' : ' ▼') : '';
                return `<th class="${hIdx >= headers.length - 2 ? 'num' : ''}" data-ind-tbl-sort="${hIdx}" style="cursor:pointer;user-select:none" title="Sort by ${esc(h)}">${esc(h)}${arrow}</th>`;
              }).join('')}</tr>
            </thead>
            <tbody>
              ${sortedRows.length ? sortedRows.map((r, rIdx) => `
                <tr class="rrow" data-ind-inspect-row="${rIdx}" data-ind-row-id="${esc(r[0])}" data-ind-inspect-surface="tables">${r.map((c, idx) => `<td class="${idx >= r.length - 2 ? 'num' : ''}">${idx === 0 ? `<b>${esc(c)}</b>` : esc(c)}</td>`).join('')}</tr>
              `).join('') : emptyRow(headers.length, 'No records match the active filter')}
            </tbody>
            <tfoot>
              <tr class="total-row">${dynTotals.map((t, idx) => `<td class="${idx >= dynTotals.length - 2 ? 'num' : ''}"><b>${esc(t)}</b></td>`).join('')}</tr>
            </tfoot>
          </table>
        </div>
      </div>
    `;
  }

  // ============================================================================
  // PHASE 8 — MULTI-INDUSTRY DOUBLE-ENTRY GL/SOA/CASHBOOK ENGINE, 360° DOMAIN
  //           INSPECTOR & SMART ENTRY QUICK-SWITCH BAR ACROSS ALL 5 VERTICALS
  // ============================================================================
  const _indGlModelCache = new Map();

  function getIndustryKpiSnapshot(ind, rawKey, baseKpi) {
    const rollup = computeEnterpriseRollup();
    const kKey = rawKey === 'company4235' ? '4235company' : (rawKey === 'insuranceco' ? 'insurance' : rawKey);
    const entHit = (rollup.entities || []).find(e => e.key === kKey);
    const indKeyMap = {
      'Holding & Treasury': 'hld',
      'Hospitality & Resorts': 'hsp',
      'Automotive & Heavy Trading': 'trd',
      'Real Estate & Property': 're',
      'Insurance & Brokerage': 'ins'
    };
    const src = (ind === 'Holding & Treasury')
      ? rollup.totals
      : (entHit ? entHit.k : (rollup.byIndustry[indKeyMap[ind]] || rollup.totals));
    const cashTill = round2(Number(src.cash_till || 48500));
    const cashIn = round2(Math.max(cashTill + Number(src.expenses || 0), Number(src.sales_ttc || 0) * 0.72, 65000));
    const cashOut = round2(Math.max(0, cashIn - cashTill));
    return Object.assign({}, baseKpi || {}, {
      loads: Number(src.loads || 0),
      sales_ttc: round2(Number(src.sales_ttc || 0)),
      net_sales: round2(Number(src.net_sales || 0)),
      raw_cost: round2(Number(src.raw_cost || 0)),
      gross_margin: round2(Number(src.gross_margin || 0)),
      expenses: round2(Number(src.expenses || 0)),
      salaries: round2(Number(src.salaries || 0)),
      operating_profit: round2(Number(src.operating_profit || 0)),
      ar_balance: round2(Number(src.ar_balance || 0)),
      ap_balance: round2(Number(src.ap_balance || 0)),
      cash_till: cashTill,
      cash_till_usd: cashTill,
      cash_till_lbp: 0,
      cash_in_usd: cashIn,
      cash_out_usd: cashOut,
      net_cash_usd: cashTill,
      net_cash_lbp: 0,
      tb_check: 0,
      rate_lbp: 89500
    });
  }

  function buildIndustryCashMoves(ind, rawKey, opts = {}) {
    const kSnap = getIndustryKpiSnapshot(ind, rawKey, {});
    const coLbl = COMPANY_LABELS[rawKey] || (ind === 'Holding & Treasury' ? 'Bdeir Holding' : ind);
    const rows = [];
    const addMv = (id, date, company, stream, cat, party, detail, ref, method, usdVal, lbpVal = 0, rkeyOverride = '', rawObj = null) => {
      const uVal = round2(Number(usdVal || 0));
      const lVal = Math.round(Number(lbpVal || 0));
      if (Math.abs(uVal) < 0.01 && Math.abs(lVal) <= 1) return;
      const dt = String(date || '2026-10-28').slice(0, 10);
      rows.push({
        id,
        rkey: rkeyOverride || (stream === 'sales' ? 'sales_tickets' : (stream === 'exp' ? 'expenses' : 'external_movements')),
        date: dt,
        ym: dt.slice(0, 7),
        company,
        stream,
        dir: (uVal > 0.005 || (Math.abs(uVal) <= 0.005 && lVal > 1)) ? 'IN' : 'OUT',
        cat,
        party,
        partyRel: '',
        detail,
        ref,
        refNum: NaN,
        method,
        usd: uVal,
        in_usd: uVal > 0 ? uVal : 0,
        out_usd: uVal < 0 ? round2(-uVal) : 0,
        lbp: lVal,
        ticketId: '',
        raw: rawObj || { id, date: dt, company, party, notes: detail, total: Math.abs(uVal) }
      });
    };

    if (ind === 'Holding & Treasury') {
      const ic = computeIntercompanyInteractions({ ignoreSearch: true, ignorePeriod: Boolean(opts.ignorePeriod) });
      (ic.interactions || []).filter(r => r.fromCo !== 'Bdeir Holding' && r.toCo !== 'Bdeir Holding').slice(0, 8).forEach((r, idx) => {
        addMv(`hld-mv-${idx + 1}`, r.date || '2026-10-28', 'Bdeir Holding', 'ext', 'Intercompany Sister Transfer', `${r.fromCo} / ${r.toCo}`, `${r.matchType} · ${r.notes || 'Sister treasury clearing'}`, r.id || `IC-${100 + idx}`, 'Bank Wire', idx % 2 === 0 ? r.usd : -r.usd);
      });
      ((SEED && SEED.records && SEED.records.external_movements) || []).forEach(ex => {
        if (!ex || ex.voided || ex.company !== 'Bdeir Holding' || ex._multiIndustrySeed || isAppRecord(ex)) return;
        const isExtd = /^extended$/i.test(String(ex.kind || ''));
        const flowStr = String(ex.flow || ex.method || '').trim();
        const isCfg = /^config$/i.test(flowStr);
        const lbpRaw = Number(ex.lbp_amount || 0);
        const usdRaw = lbpRaw ? Number(ex.usd_amount || 0) : Number(ex.usd_amount != null ? ex.usd_amount : (ex.amount || 0));
        let usd = 0, lbp = 0, cat = '', methodLbl = '';
        if (isCfg) {
          usd = round2(usdRaw);
          lbp = Math.round(lbpRaw);
          cat = isExtd ? 'Extended Opening' : 'External Opening';
          methodLbl = 'Opening';
        } else {
          const isOut = /out|expense|withdraw|debit/i.test(String(ex.direction || flowStr));
          usd = isOut ? -round2(Math.abs(usdRaw)) : round2(Math.abs(usdRaw));
          lbp = isOut ? -Math.round(Math.abs(lbpRaw)) : Math.round(Math.abs(lbpRaw));
          cat = isExtd ? (isOut ? 'Extended Out' : 'Extended In') : (isOut ? 'External Out' : 'External In');
          methodLbl = cat;
        }
        addMv(ex.id, ex.date, 'Bdeir Holding', isExtd ? 'extd' : 'ext', cat, ex.counterparty || (isExtd ? 'Extended Stakeholder' : 'External Treasury'), cleanLedgerNote(ex.notes) || cat, shortVoucherRef(ex.reference || ex.name || ex.id), methodLbl, usd, lbp, 'external_movements', ex);
      });
      addMv('hld-mv-9', '2026-10-30', 'Bdeir Holding', 'loan', 'Partner Distribution Pool', 'Shareholder Pool (10 Slots)', 'Monthly group treasury settlement', 'HLD-4515-10', 'Bank Transfer', 42500);
      addMv('hld-mv-10', '2026-10-29', 'Bdeir Holding', 'exp', 'Corporate Shared Services', 'Bdeir Holding HQ', 'Group audit, legal & cloud infrastructure', 'HLD-EXP-22', 'Cash', -14200);
    } else if (ind === 'Hospitality & Resorts') {
      const hsp = computeHospitalityOperations({ ignoreSearch: true, company: rawKey });
      (hsp.venueRows || []).slice(0, 6).forEach((r, idx) => {
        addMv(`hsp-mv-${idx + 1}`, r.date || '2026-10-28', r.company, 'sales', `${r.category} Close`, r.outlet, `${r.covers || 0} covers · POS Till Close Tied`, r.id, r.method || 'Cash', r.ttc_usd);
      });
      (hsp.membershipRows || []).slice(0, 3).forEach((m, idx) => {
        addMv(`hsp-mem-${idx + 1}`, m.due_date || '2026-10-25', m.company, 'sales', 'Seasonal Membership Collection', m.member, `${m.unit} (${m.season})`, m.id, 'Cash', m.paid_usd);
      });
      (hsp.stockRows || []).slice(0, 3).forEach((st, idx) => {
        addMv(`hsp-stk-${idx + 1}`, '2026-10-26', st.company, 'exp', 'Commissary & Cellar Replenishment', st.store, `Purchases In (${st.r3_ratio.toFixed(2)}x usage ratio)`, st.id, 'Cash', -round2(st.purchases_in_usd * 0.45));
      });
    } else if (ind === 'Automotive & Heavy Trading') {
      const trd = computeTradingOperations({ ignoreSearch: true, company: rawKey });
      (trd.salesRows || []).filter(r => !r.is_gap).slice(0, 6).forEach((r, idx) => {
        addMv(`trd-mv-${idx + 1}`, r.date || '2026-10-28', r.company, 'sales', `Invoice Book ${r.book}`, r.customer, `${r.item} (Qty ${r.qty})`, r.id, r.payment_term === 'Cash' ? 'Cash' : 'Cheque / Wire', r.ttc_usd);
      });
      (trd.importRows || []).slice(0, 4).forEach((im, idx) => {
        const impCost = Number(im.landed_add_usd != null ? im.landed_add_usd : (Number(im.customs_usd || 0) + Number(im.freight_usd || 0) + Number(im.clearance_usd || 0))) || round2(Number(im.total_landed_usd || im.fob_usd || 0) * 0.12);
        addMv(`trd-imp-${idx + 1}`, im.date || im.eta_date || '2026-10-22', im.company, 'exp', 'Import Customs & Freight', im.supplier, `${im.container_bl || im.container_ref || im.id} · ${im.origin || im.origin_port || 'Port'}`, im.id, 'LC / Wire', -round2(impCost));
      });
    } else if (ind === 'Real Estate & Property') {
      const re = computeRealEstateOperations({ ignoreSearch: true, company: rawKey });
      (re.invoices || []).slice(0, 6).forEach((inv, idx) => {
        addMv(`re-mv-${idx + 1}`, inv.date || '2026-10-25', inv.company, 'sales', 'Commercial & Residential Rent Receipt', inv.tenant, `${inv.property} · ${inv.period} (${inv.tax_seq || inv.seq_no || inv.id})`, inv.id, 'Bank / Cash', Number(inv.collected_usd || inv.paid_usd || inv.amount_ttc_usd || inv.ttc_usd || 0));
      });
      (re.workorders || re.workOrders || []).slice(0, 4).forEach((wo, idx) => {
        addMv(`re-wo-${idx + 1}`, wo.date || '2026-10-21', wo.company, 'exp', 'Fit-Out & Building Work Order', wo.contractor, `${wo.property} · ${wo.unit} (${wo.category || wo.scope || 'Works'})`, wo.id, 'Cash', -Number(wo.actual_usd || 0));
      });
    } else {
      const ins = computeInsuranceOperations();
      (ins.billing || []).slice(0, 6).forEach((b, idx) => {
        addMv(`ins-mv-${idx + 1}`, b.date || b.due_date || '2026-10-27', 'Insurance Company', 'sales', 'Policyholder Premium Collection', b.client, `Policy ${b.policy_no || b.policy_id || b.id} · ${b.carrier}`, b.id, 'Cash / Wire', Number(b.collected_usd || b.paid_usd || b.client_billed_4112_usd || b.gross_prem_usd || 0));
      });
      (ins.remittances || ins.statements || []).slice(0, 4).forEach((st, idx) => {
        const remOut = Number(st.settled_to_carrier_usd || st.net_payable_4017_usd || st.statement_comm_usd || 8500);
        addMv(`ins-st-${idx + 1}`, st.next_due || '2026-10-24', 'Insurance Company', 'exp', 'Carrier Net Premium Remittance', st.carrier, `Bordereau ${st.period || st.settlement_mode || 'Monthly'}`, st.id, 'Bank Wire', -round2(remOut * 0.6));
      });
    }

    const effScopeKey = rawKey || STATE.company || ('industry:' + ind);
    const allowed = allowedCompanyNames(opts.user);
    const matchCo = r => matchesCashScopeCompany(r, effScopeKey, allowed);
    for (let ri = rows.length - 1; ri >= 0; ri--) {
      if (!matchCo(rows[ri])) rows.splice(ri, 1);
    }

    if (!rows.length) {
      const fallbackCo = COMPANY_BU_MATCH[effScopeKey] || coLbl;
      if (!Array.isArray(allowed) || !allowed.length || allowed.includes(fallbackCo)) {
        addMv('ind-mv-1', '2026-10-28', fallbackCo, 'sales', 'Operating Cash Inflow', fallbackCo, 'Verified domain treasury receipt', 'DOC-001', 'Cash', kSnap.cash_in_usd || 75000);
        addMv('ind-mv-2', '2026-10-27', fallbackCo, 'exp', 'Operating Cash Outflow', fallbackCo, 'Verified domain supplier settlement', 'DOC-002', 'Cash', -(kSnap.cash_out_usd || 26500));
      }
    }

    if (!opts.baselineOnly && STATE.customRecords) {
      forEachCashCustomDelta('sales_tickets', matchCo, (t, mult) => {
        if (isRemovedTicket(t) || !isCashSaleTicket(t)) return;
        const sgn = ticketSign(t);
        if (!sgn) return;
        const u = round2(mult * salesCashMoveAmount(t));
        const l = Math.round(mult * sgn * Number(t.vat || 0) * 89500);
        addMv(t.id, t.date, t.company, 'sales', 'Cash Sale', t.customer || 'Cash Customer', t.product || t.notes || 'Cash sale', String(t.ticket_no || t.id || ''), t.method || 'Cash', u, l, 'sales_tickets', t);
      });
      forEachCashCustomDelta('receipts', matchCo, (rc, mult) => {
        const mth = String(rc.method || '').trim();
        const knd = receiptKind(rc);
        if (knd !== 'Settlement' && knd !== 'VAT received' && mth !== 'Rent' && mth !== 'VATRent') return;
        const lRaw = Number(rc.lbp_amount || 0);
        const u = mth === 'Rent' ? -round2(mult * Number(rc.usd_amount != null ? rc.usd_amount : rc.amount || 0))
          : (knd === 'Settlement' ? round2(mult * (lRaw ? Number(rc.usd_amount || 0) : Number(rc.usd_amount != null ? rc.usd_amount : rc.amount || 0))) : 0);
        const l = mth === 'VATRent' ? -Math.round(mult * (lRaw || ((Number(rc.amount || 0) + Number(rc.discount || 0)) * 89500)))
          : (knd === 'VAT received' ? Math.round(mult * (lRaw || (Number(rc.amount || 0) * 89500))) : Math.round(mult * lRaw));
        addMv(rc.id, rc.date, rc.company, 'sales', 'Customer Receipt', rc.customer || 'Customer', rc.notes || 'Customer settlement', String(rc.reference || rc.id || ''), mth || 'Cash', u, l, 'receipts', rc);
      });
      forEachCashCustomDelta('expenses', matchCo, (e, mult) => {
        if (e.price_pending || isCreditExpense(e)) return;
        const sgn = expenseSign(e);
        if (!sgn) return;
        const lRaw = Number(e.lbp_amount || 0);
        const u = -round2(mult * sgn * (lRaw ? Number(e.usd_amount || 0) : Number(e.usd_amount != null ? e.usd_amount : e.amount || 0)));
        const l = -Math.round(mult * sgn * lRaw);
        addMv(e.id, e.date, e.company, 'exp', e.category || 'Cash Expense', e.supplier || e.subcategory || 'Expense', e.notes || e.item_summary || 'Operating expense', String(e.reference || e.id || ''), e.method || 'Cash', u, l, 'expenses', e);
      });
      forEachCashCustomDelta('settlements', matchCo, (sp, mult) => {
        const knd = settlementKind(sp);
        if (knd !== 'Payment' && knd !== 'VAT paid') return;
        const lRaw = Number(sp.lbp_amount || 0);
        const u = knd === 'Payment' ? -round2(mult * (lRaw ? Number(sp.usd_amount || 0) : Number(sp.usd_amount != null ? sp.usd_amount : sp.amount || 0))) : 0;
        const l = knd === 'Payment' ? -Math.round(mult * lRaw) : -Math.round(mult * (lRaw || Math.round(Number(sp.amount || 0) * 89500)));
        addMv(sp.id, sp.date, sp.company, 'exp', 'Supplier Settlement', sp.supplier || 'Supplier', sp.notes || 'Supplier payment', String(sp.reference || sp.id || ''), sp.method || 'Payment', u, l, 'settlements', sp);
      });
      forEachCashCustomDelta('external_movements', matchCo, (ex, mult) => {
        const flowStr = String(ex.flow || ex.type || '');
        const isExtd = /extended/i.test(String(ex.kind || flowStr)) || /^Extended\./i.test(String(ex.notes || ''));
        const isOut = /out|expense/i.test(String(ex.direction || flowStr));
        const lRaw = Math.abs(Number(ex.lbp_amount || 0));
        const uRaw = Math.abs(lRaw ? Number(ex.usd_amount || 0) : Number(ex.usd_amount != null ? ex.usd_amount : ex.amount || 0));
        const sgn = isOut ? -1 : 1;
        addMv(ex.id, ex.date, ex.company, isExtd ? 'extd' : 'ext', isExtd ? (isOut ? 'Extended Out' : 'Extended In') : (isOut ? 'External Out' : 'External In'), ex.counterparty || 'External Treasury', ex.notes || 'External movement', String(ex.reference || ex.id || ''), ex.direction || (isOut ? 'External Out' : 'External In'), mult * sgn * uRaw, mult * sgn * lRaw, 'external_movements', ex);
      });
      forEachCashCustomDelta('conversions', matchCo, (cv, mult) => {
        const d = convSignedDeltas(cv, 89500);
        addMv(cv.id, cv.date, cv.company, 'fx', d.dirLabel || 'FX Conversion', 'FX Desk', cv.notes || d.dirLabel || 'Currency exchange', String(cv.reference || cv.id || ''), d.dirLabel || 'FX', mult * d.usd, mult * d.lbp, 'conversions', cv);
      });
    }

    const range = opts.ignorePeriod ? null : (opts.range !== undefined ? opts.range : periodRange(STATE.period));
    if (range) {
      return rows.filter(mv => !mv.date || ((!range.from || mv.date >= range.from) && (!range.to || mv.date <= range.to)));
    }
    return rows;
  }

