      const transIsTruck = hasTrans && effRatePer === 'Truck';
      const effUp = (!hasMat || matIsTruck) ? 0 : up0;
      const effTp = (!hasTrans || transIsTruck) ? 0 : tp0;
      const effIndiff = matIsTruck ? (up0 || null) : ((isTransOnly && transIsTruck) ? (tp0 || null) : null);
