      const uom = (catItem && catItem.uom) ? catItem.uom : (val('f_uom') || 'Piece');
      const whIdx = getWarehouseIndex(company);
      const curItem = itemName ? whIdx.byKey[norm(itemName)] : null;
      let beforeQty = curItem ? curItem.onHandQty : 0;
