  function getActiveIndustry(coKey) {
    const k = String(coKey || STATE.company || 'manufacturing-group');
    if (k === 'manufacturing-group' || k === 'ALL') return 'Manufacturing';
    if (k === 'bdeirholding') return 'Holding & Treasury';
    if (k.startsWith('industry:')) {
      const slug = k.slice(9).trim();
      const sl = slug.toLowerCase();
      if (sl === 'holding' || sl === 'holding & treasury') return 'Holding & Treasury';
      if (sl === 'hospitality' || sl === 'hospitality & resorts') return 'Hospitality & Resorts';
      if (sl === 'trading' || sl === 'automotive & heavy trading') return 'Automotive & Heavy Trading';
      if (sl === 'realestate' || sl === 'real estate' || sl === 'real estate & property') return 'Real Estate & Property';
      if (sl === 'insurance' || sl === 'insurance & brokerage') return 'Insurance & Brokerage';
      if (sl === 'manufacturing') return 'Manufacturing';
      return slug || 'Manufacturing';
    }
    if (COMPANY_INDUSTRY_BY_KEY[k]) return COMPANY_INDUSTRY_BY_KEY[k];
    const cat = getCompanyCatalog();
    const hit = cat.find(c => c.key === k || c.name.toLowerCase() === k.toLowerCase());
    return (hit && hit.industry) || 'Manufacturing';
  }
  window.__mfgGetActiveIndustry = getActiveIndustry;

  function resolveIndustryCompatibleView(view, targetInd) {
    const effInd = (targetInd && INDUSTRY_SIDEBAR_SPEC[targetInd])
      ? targetInd
      : (INDUSTRY_SIDEBAR_SPEC[getActiveIndustry(STATE.company)] ? getActiveIndustry(STATE.company) : 'Manufacturing');
    const nextSpec = INDUSTRY_SIDEBAR_SPEC[effInd] || INDUSTRY_SIDEBAR_SPEC['Manufacturing'];
    const curHub = VIEW_TO_HUB[view] || view;
    const allSpecs = Object.values(INDUSTRY_SIDEBAR_SPEC);
    for (let i = 0; i < allSpecs.length; i++) {
      const sIdx = allSpecs[i].slots.findIndex(s => s.hub === curHub);
      if (sIdx >= 0) {
        if (nextSpec.slots[sIdx] && nextSpec.slots[sIdx].hub !== curHub) {
          return nextSpec.slots[sIdx].view;
        }
        return view;
      }
    }
    const hubDef = getHubDef(curHub);
    if (hubDef && hubDef.industry && hubDef.industry !== effInd) {
      return (nextSpec.slots[0] && nextSpec.slots[0].view) || 'overview';
    }
    return view;
  }

  let _lastSyncedSidebarInd = 'Manufacturing';
  function syncIndustrySidebarDom(indId) {
    const effInd = (indId && INDUSTRY_SIDEBAR_SPEC[indId]) ? indId : (INDUSTRY_SIDEBAR_SPEC[getActiveIndustry(STATE.company)] ? getActiveIndustry(STATE.company) : 'Manufacturing');
    const navEl = $('sidebarNav');
    if (!navEl) return;
    const spec = INDUSTRY_SIDEBAR_SPEC[effInd] || INDUSTRY_SIDEBAR_SPEC['Manufacturing'];
    const grps = navEl.querySelectorAll('.grp');
    if (grps[1] && grps[1].textContent !== spec.grp1) grps[1].textContent = spec.grp1;
    if (grps[2] && grps[2].textContent !== spec.grp2) grps[2].textContent = spec.grp2;

    // The 4 swappable operational hub buttons sit at indices 3, 4 (before expenses at 5) and 6, 7 (before payroll at 8)
    const navBtns = navEl.querySelectorAll('button.nav-item');
    const slotIndices = [3, 4, 6, 7];
    const activeHubId = VIEW_TO_HUB[STATE.view] || 'overview';
    slotIndices.forEach((btnIdx, slotIdx) => {
      const btn = navBtns[btnIdx];
      const slot = spec.slots[slotIdx];
      if (!btn || !slot) return;
      const prevHub = btn.getAttribute('data-hub');
      if (prevHub !== slot.hub) {
        btn.setAttribute('data-hub', slot.hub);
        btn.setAttribute('data-view', slot.view);
        btn.setAttribute('aria-label', slot.label);
        const icoEl = btn.querySelector('.nav-ico');
        if (icoEl && window.MFG_ICONS) {
          icoEl.outerHTML = window.MFG_ICONS.nav(slot.view);
        }
        const lblSpan = btn.querySelector('span');
        if (lblSpan) lblSpan.textContent = slot.label;
      }
      btn.classList.toggle('on', slot.hub === activeHubId);
    });
    _lastSyncedSidebarInd = effInd;
  }

  function getInitials(name) {
    return String(name || 'IS').split(/\s+/).filter(Boolean).slice(0, 2).map(p => p[0].toUpperCase()).join('');
  }

  function selectCompanyScope(coKey, closePopover = true) {
    if (!coKey) return;
    const prevInd = getActiveIndustry(STATE.company);
    const nextInd = getActiveIndustry(coKey);
    const prevView = STATE.view;
    STATE.company = coKey;
    STATE.shown = {};
    STATE.pbiTablePage = {};
    const nextView = resolveIndustryCompatibleView(STATE.view, nextInd);
    if (prevInd !== nextInd) {
      const defStmtByInd = {
        'Manufacturing': '01',
        'Holding & Treasury': '23',
        'Hospitality & Resorts': '24',
        'Automotive & Heavy Trading': '25',
        'Real Estate & Property': '26',
        'Insurance & Brokerage': '27'
      };
      STATE.activeStatement = defStmtByInd[nextInd] || '01';
    }
    if (nextView !== STATE.view || prevInd !== nextInd) {
      STATE.view = nextView;
      STATE.search = '';
      STATE.chipFilter = 'all';
      STATE._resetWorkspaceScroll = true;
      _preModalWorkspaceScrollSnap = null;
      _preModalWorkspaceScope = '';
      const ws = $('workspace');
      if (ws && ws.scrollTop !== 0) ws.scrollTop = 0;
    }
    if (STATE.authed && VIEW_TITLES[STATE.view]) {
      const targetHash = '#' + STATE.view;
      if (location.hash !== targetHash || STATE.view !== prevView) {
        try {
          history.replaceState({ view: STATE.view, company: STATE.company }, '', targetHash);
        } catch (_) {}
        if (location.hash !== targetHash) {
          try { location.hash = targetHash; } catch (__) {}
        }
      }
    }
    syncIndustrySidebarDom(nextInd);
    saveFilterState();
    if (closePopover) {
      const switchEl = $('companySwitch');
      const popEl = $('companySwitchPopover');
      const trigEl = $('companySwitchTrigger');
      if (switchEl) switchEl.classList.remove('open');
      if (popEl) popEl.hidden = true;
      if (trigEl) trigEl.setAttribute('aria-expanded', 'false');
    }
    renderApp();
  }

  let _companySwitchUiSig = '';
  function syncCompanySwitchUi() {
    const switchEl = $('companySwitch');
    if (!switchEl) return;
    const user = activeUser();
    const allowedCos = getAllowedCompanyKeys(user);
    const allowedNames = allowedCompanyNames(user);
    const catalog = getCompanyCatalog();
    const searchInpEarly = $('companySwitchSearch');
    const qEarly = searchInpEarly ? String(searchInpEarly.value || '').trim().toLowerCase() : '';
    const uiSig = `${(user && user.id) || ''}|${allowedCos.join(',')}|${allowedNames.join(',')}|${catalog.length}|${_companyCatalogSig}|${STATE.company}|${STATE.companySwitchIndFilter || 'all'}|${qEarly}|${Boolean(STATE.demoVisitor)}|${isOfficialScopeActive(user)}|${Boolean(STATE.enterpriseScalePreview)}`;
    if (_companySwitchUiSig === uiSig && switchEl.querySelector('.entity-btn')) return;
    _companySwitchUiSig = uiSig;
    const allowedNameSet = new Set(allowedNames.map(n => n.toLowerCase()));
    const indGroups = getIndustryGroups(catalog);
    const coFreqSwitch = (_FREQ_IDX && _FREQ_IDX.company) ? _FREQ_IDX.company : null;
    const listEl = $('companySwitchList') || switchEl;

    // Allowed industries for this user — ranked strictly by summed operational frequency of permitted companies
    const allowedIndGroups = indGroups.map(g => {
      const permittedCos = g.companies.filter(c => allowedNameSet.has(c.name.toLowerCase()));
      const permittedFreq = (coFreqSwitch && coFreqSwitch.size)
        ? permittedCos.reduce((s, c) => s + (coFreqSwitch.get(norm(c.name)) || 0), 0)
        : (g.freq || 0);
      return { ...g, permittedCos, permittedFreq };
    }).filter(g => g.permittedCos.length > 0);
    if (coFreqSwitch && coFreqSwitch.size) {
      allowedIndGroups.sort((a, b) => (b.permittedFreq || 0) - (a.permittedFreq || 0));
    }
    const orderedSwitchGroups = allowedIndGroups.concat(indGroups.filter(g => !allowedIndGroups.some(ag => ag.id === g.id)));

    // Order each industry's consolidated group row directly above its member companies (preserving MFG_FREQ industry & company rank)
    const desiredKeys = [];
    orderedSwitchGroups.forEach(g => {
      if (g.id === 'Manufacturing' && allowedCos.includes('manufacturing-group')) {
        desiredKeys.push('manufacturing-group');
      }
      const indKey = `industry:${g.id}`;
      if (indGroups.length >= 2 && allowedCos.includes(indKey) && !desiredKeys.includes(indKey)) {
        desiredKeys.push(indKey);
      }
      g.companies.forEach(c => {
        if (!desiredKeys.includes(c.key)) desiredKeys.push(c.key);
      });
    });
    if (!desiredKeys.includes('manufacturing-group')) desiredKeys.unshift('manufacturing-group');
    catalog.forEach(c => { if (!desiredKeys.includes(c.key)) desiredKeys.push(c.key); });
    allowedCos.forEach(k => { if (!desiredKeys.includes(k)) desiredKeys.push(k); });

    desiredKeys.forEach(coKey => {
      let btn = switchEl.querySelector(`.entity-btn[data-company="${coKey}"]`);
      if (!btn) {
        btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'entity-btn';
        btn.setAttribute('data-company', coKey);
        if (coKey.startsWith('industry:')) {
          btn.textContent = `All ${coKey.slice(9)}`;
        } else {
          btn.textContent = COMPANY_BU_MATCH[coKey] || coKey;
        }
        btn.addEventListener('click', e => {
          e.stopPropagation();
          selectCompanyScope(coKey, true);
        });
      }
      btn.classList.toggle('is-group-scope', coKey === 'manufacturing-group' || coKey.startsWith('industry:'));
      listEl.appendChild(btn);
    });

    const allowedIndCount = Math.max(1, allowedIndGroups.length);
    const firstAllowedInd = allowedIndGroups[0] ? allowedIndGroups[0].id : 'Manufacturing';
    const liveInd = getActiveIndustry(STATE.company);

    if (STATE.companySwitchIndFilter !== 'all' && !allowedIndGroups.some(g => g.id === STATE.companySwitchIndFilter)) {
      STATE.companySwitchIndFilter = 'all';
    }

    const indHeadEl = $('companySwitchIndHead');
    if (indHeadEl) {
      indHeadEl.textContent = `Industries (${allowedIndCount})`;
    }

    // Populate Left Column: Industry Tabs (#companySwitchIndustryList)
    const indListEl = $('companySwitchIndustryList');
    if (indListEl) {
      const isExactIndMatch = g => {
        const ql = qEarly;
        if (!ql) return false;
        const idL = String(g.id || '').toLowerCase();
        const lblL = String(g.label || '').toLowerCase();
        const codeL = String(g.code || '').toLowerCase();
        const shortL = lblL.split(/\s*&\s*/)[0].trim();
        return idL === ql || lblL === ql || codeL === ql || shortL === ql;
      };
      const displayIndGroups = qEarly
        ? allowedIndGroups.filter(isExactIndMatch).concat(allowedIndGroups.filter(g => !isExactIndMatch(g)))
        : allowedIndGroups;
      const indTabsHtml = [
        `<button type="button" class="ep-ind-tab ${STATE.companySwitchIndFilter === 'all' ? 'active' : ''}" data-ep-ind="all" data-ui-tip="Show all ${allowedNames.length} permitted companies across ${allowedIndCount} industries">
          <span class="ep-ind-tab-name">All Industries</span>
          <em class="ep-ind-tab-cnt">${allowedNames.length}</em>
        </button>`
      ].concat(displayIndGroups.map(g => `
        <button type="button" class="ep-ind-tab ${STATE.companySwitchIndFilter === g.id ? 'active' : ''}" data-ep-ind="${esc(g.id)}" data-ui-tip="${esc(g.label)} (${g.permittedCos.length} permitted${g.id === liveInd ? ' · Active' : ''})">
          <span class="ep-ind-tab-name">${g.id === liveInd ? '<span class="ep-ind-live-dot" aria-hidden="true"></span>' : ''}${esc(g.label)}</span>
          <em class="ep-ind-tab-cnt">${g.permittedCos.length}</em>
        </button>
      `)).join('');
      indListEl.innerHTML = indTabsHtml;
      indListEl.querySelectorAll('[data-ep-ind]').forEach(tabBtn => {
        tabBtn.addEventListener('click', e => {
          e.stopPropagation();
          const pickedInd = tabBtn.getAttribute('data-ep-ind') || 'all';
          STATE.companySwitchIndFilter = pickedInd;
          if (searchInpEarly && searchInpEarly.value) searchInpEarly.value = '';
          if (pickedInd === 'all') {
            syncCompanySwitchUi();
            return;
          }
          const grp = allowedIndGroups.find(g => g.id === pickedInd);
          const targetKey = pickedInd === 'Manufacturing'
            ? (allowedCos.includes('manufacturing-group') ? 'manufacturing-group' : (grp && grp.permittedCos[0] ? grp.permittedCos[0].key : 'wtc'))
            : (grp && grp.permittedCos.length === 1 ? grp.permittedCos[0].key : `industry:${pickedInd}`);
          if (getActiveIndustry(STATE.company) !== pickedInd || STATE.company !== targetKey || resolveIndustryCompatibleView(STATE.view, pickedInd) !== STATE.view) {
            selectCompanyScope(targetKey, false);
            return;
          }
          syncCompanySwitchUi();
        });
      });
    }

    const searchInp = $('companySwitchSearch');
    const q = searchInp ? String(searchInp.value || '').trim().toLowerCase() : '';
    const indFilter = q ? 'all' : (STATE.companySwitchIndFilter || 'all');

    const mfgAllowedCount = STATE.enterpriseScalePreview
      ? allowedNames.length
      : allowedNames.filter(n => !/^(bdeir\s*holding|blanca|la\s*una|palms|voile|platinum|korri\s*auto|shacman|properties|4235\s*company(\s*s\.?a\.?l\.?)?|insurance\s*company)$/i.test(n)).length;
    const mfgCatalogCount = STATE.enterpriseScalePreview
      ? catalog.length
      : catalog.filter(c => !['bdeirholding', 'blanca', 'launa', 'palms', 'voile', 'platinum', 'korriauto', 'shacman', 'properties', '4235company', 'insurance'].includes(c.key)).length;

    let visibleBtnCount = 0;
    const exactBtns = [];
    const freqBtns = [];
    switchEl.querySelectorAll('.entity-btn').forEach(btn => {
      btn.classList.remove('kbd-focus');
      const key = btn.getAttribute('data-company') || '';
      const isAllowed = allowedCos.includes(key);
      if (key === 'manufacturing-group') {
        btn.textContent = mfgAllowedCount >= mfgCatalogCount
          ? `All Group (${mfgAllowedCount})`
          : `All Assigned (${mfgAllowedCount})`;
        btn.setAttribute('data-ind', 'all');
        btn.setAttribute('data-ind-tag', STATE.enterpriseScalePreview && allowedIndCount > 1 ? `${allowedIndCount} Ind` : firstAllowedInd);
        btn.setAttribute('data-co-search', `all group assigned consolidated manufacturing ${allowedNames.join(' ').toLowerCase()}`);
      } else if (key.startsWith('industry:')) {
        const indName = key.slice(9);
        const grp = allowedIndGroups.find(g => g.id === indName);
        const cnt = grp ? grp.permittedCos.length : 0;
        btn.textContent = `All ${indName} (${cnt})`;
        btn.setAttribute('data-ind', indName);
        btn.setAttribute('data-ind-tag', `All · ${cnt}`);
        btn.setAttribute('data-co-search', `all ${indName.toLowerCase()} industry consolidated`);
      } else {
        const coMeta = catalog.find(c => c.key === key);
        const indName = (coMeta && coMeta.industry) || COMPANY_INDUSTRY_BY_KEY[key] || 'Manufacturing';
        btn.setAttribute('data-ind', indName);
        btn.setAttribute('data-ind-tag', indName);
        btn.setAttribute('data-co-search', ((coMeta ? `${coMeta.name} ${coMeta.label} ${coMeta.sector} ${indName} ${coMeta.key}` : `${btn.textContent} ${key}`)).toLowerCase());
      }

      if (!isAllowed) {
        btn.hidden = true;
      } else {
        const btnInd = btn.getAttribute('data-ind') || 'Manufacturing';
        const hay = btn.getAttribute('data-co-search') || btn.textContent.toLowerCase();
        let matchInd = indFilter === 'all' ? true : (key === 'manufacturing-group' ? indFilter === 'Manufacturing' : btnInd === indFilter);
        if (key === 'industry:Manufacturing' && allowedCos.includes('manufacturing-group') && !STATE.enterpriseScalePreview && STATE.company !== key) {
          matchInd = false;
        } else if (key.startsWith('industry:') && !STATE.enterpriseScalePreview && STATE.company !== key) {
          const grp = allowedIndGroups.find(g => g.id === key.slice(9));
          if (!grp || grp.permittedCos.length < 2) matchInd = false;
        }
        const matchQ = !q || hay.includes(q);
        btn.hidden = !(matchInd && matchQ);
        if (!btn.hidden) {
          visibleBtnCount += 1;
          if (q) {
            const labelNorm = btn.textContent.trim().toLowerCase();
            if (labelNorm === q || key.toLowerCase() === q) exactBtns.push(btn);
            else freqBtns.push(btn);
          }
        }
      }
      btn.classList.toggle('active', key === STATE.company);
    });

    if (q && (exactBtns.length || freqBtns.length)) {
      if (freqBtns.length > 1 && coFreqSwitch && coFreqSwitch.size) {
        const btnFreqScore = btn => {
          const bk = btn.getAttribute('data-company') || '';
          if (bk === 'manufacturing-group') {
            const mg = allowedIndGroups.find(g => g.id === 'Manufacturing');
            return mg ? (mg.permittedFreq || 0) : 0;
          }
          if (bk.startsWith('industry:')) {
            const ig = allowedIndGroups.find(g => g.id === bk.slice(9));
            return ig ? (ig.permittedFreq || 0) : 0;
          }
          const coName = COMPANY_BU_MATCH[bk] || bk;
          return coFreqSwitch.get(norm(coName)) || 0;
        };
        freqBtns.sort((a, b) => btnFreqScore(b) - btnFreqScore(a));
      }
      exactBtns.concat(freqBtns).forEach(btn => listEl.appendChild(btn));
    }

    // Update Trigger Box 2-Segment Labels (IND + CO)
    const indTextEl = $('companySwitchIndText');
    const coTextEl = $('companySwitchCoText');
    let trigInd = firstAllowedInd;
    let trigCo = `All Group (${mfgAllowedCount})`;
    if (STATE.company === 'manufacturing-group') {
      trigInd = (STATE.enterpriseScalePreview && allowedIndCount > 1) ? `All (${allowedIndCount} Ind)` : firstAllowedInd;
      trigCo = mfgAllowedCount >= mfgCatalogCount
        ? `All Group (${mfgAllowedCount})`
        : `All Assigned (${mfgAllowedCount})`;
    } else if (String(STATE.company || '').startsWith('industry:')) {
      const indName = String(STATE.company).slice(9);
      const grp = allowedIndGroups.find(g => g.id === indName);
      const cnt = grp ? grp.permittedCos.length : 0;
      trigInd = indName;
      trigCo = `All ${indName === 'Real Estate & Property' ? 'Real Estate' : indName.split(' ')[0]} (${cnt})`;
    } else {
      const coMeta = catalog.find(c => c.key === STATE.company);
      const rawInd = (coMeta && coMeta.industry) || COMPANY_INDUSTRY_BY_KEY[STATE.company] || 'Manufacturing';
      trigInd = rawInd;
      trigCo = (coMeta && coMeta.name) || COMPANY_BU_MATCH[STATE.company] || STATE.company;
    }
    if (indTextEl) { indTextEl.textContent = trigInd; indTextEl.setAttribute('data-ui-tip', `Click to browse all ${allowedIndCount} industries`); }
    if (coTextEl) { coTextEl.textContent = trigCo; coTextEl.setAttribute('data-ui-tip', `Click to switch companies in ${liveInd}`); }

    // Populate Quick Domain Hubs deck inside right column when a specific industry is selected
    if (listEl && listEl.parentElement) {
      let quickDeckEl = $('companySwitchQuickHubs');
      if (!quickDeckEl) {
        quickDeckEl = document.createElement('div');
        quickDeckEl.id = 'companySwitchQuickHubs';
        quickDeckEl.className = 'ep-co-quick-deck';
        listEl.parentElement.appendChild(quickDeckEl);
      }
      const quickHubsByInd = {
        'Manufacturing': [
          { view: 'overview', label: 'Overview' },
          { view: 'sales', label: 'Sales & Dispatch' },
          { view: 'raw', label: 'Quarry & Haulage' },
          { view: 'fleet', label: 'Fleet & Diesel' },
          { view: 'kiosks', label: 'Plant Kiosks' }
        ],
        'Holding & Treasury': [
          { view: 'overview', label: 'Overview' },
          { view: 'hld_consolidation', label: 'Group P&L' },
          { view: 'hld_interactions', label: 'Intercompany Hub' },
          { view: 'hld_partners', label: 'Partner Capital' },
          { view: 'hld_loans', label: 'Loans & Treasury' }
        ],
        'Hospitality & Resorts': [
          { view: 'overview', label: 'Overview' },
          { view: 'hsp_revenue', label: 'Venue Revenue' },
          { view: 'hsp_pos', label: 'POS & Shift Close' },
          { view: 'hsp_memberships', label: 'Memberships' },
          { view: 'hsp_stock', label: 'Cellar & Kitchen' }
        ],
        'Automotive & Heavy Trading': [
          { view: 'overview', label: 'Overview' },
          { view: 'trd_sales', label: 'Sales Invoices' },
          { view: 'trd_trucks', label: 'Showroom VINs' },
          { view: 'trd_stock', label: '5-Whse Parts' },
          { view: 'trd_purchases', label: 'Import Files' }
        ],
        'Real Estate & Property': [
          { view: 'overview', label: 'Overview' },
          { view: 're_properties', label: 'Properties & Map' },
          { view: 're_leases', label: 'Active Leases' },
          { view: 're_invoicing', label: 'Rent Invoices' },
          { view: 're_sales', label: 'Deed Sales' }
        ],
        'Insurance & Brokerage': [
          { view: 'overview', label: 'Overview' },
          { view: 'ins_policies', label: 'Policies & Discounts' },
          { view: 'ins_renewals', label: 'Renewal Queue' },
          { view: 'ins_billing', label: 'Client Billing' },
          { view: 'ins_statements', label: 'Carrier Recon' },
          { view: 'ins_claims', label: 'FNOL Claims' }
        ]
      };
      const deckHubs = (!q && indFilter !== 'all') ? (quickHubsByInd[indFilter] || null) : null;
      if (deckHubs && deckHubs.length) {
        const grp = allowedIndGroups.find(g => g.id === indFilter);
        const targetKey = indFilter === 'Manufacturing'
          ? (allowedCos.includes('manufacturing-group') ? 'manufacturing-group' : (grp && grp.permittedCos[0] ? grp.permittedCos[0].key : 'wtc'))
          : (grp && grp.permittedCos.length === 1 ? grp.permittedCos[0].key : `industry:${indFilter}`);
        quickDeckEl.hidden = false;
        quickDeckEl.innerHTML = `
          <div class="ep-co-quick-title">Jump Directly to ${esc(indFilter)} Hubs</div>
          <div class="ep-co-quick-chips">
            ${deckHubs.map(h => `<button type="button" class="ep-co-quick-chip" data-ep-quick-view="${esc(h.view)}" data-ep-quick-co="${esc(targetKey)}">${esc(h.label)}</button>`).join('')}
          </div>
        `;
        quickDeckEl.querySelectorAll('[data-ep-quick-view]').forEach(chip => {
          chip.addEventListener('click', ev => {
            ev.stopPropagation();
            const qView = chip.getAttribute('data-ep-quick-view') || 'overview';
            const qCo = chip.getAttribute('data-ep-quick-co') || STATE.company;
            if (getActiveIndustry(STATE.company) !== indFilter) {
              selectCompanyScope(qCo, true);
            } else {
              switchEl.classList.remove('open');
              const p = $('companySwitchPopover');
              if (p) p.hidden = true;
              const tb = $('companySwitchTrigger');
              if (tb) tb.setAttribute('aria-expanded', 'false');
            }
            setView(qView);
          });
        });
      } else {
        quickDeckEl.hidden = true;
        quickDeckEl.innerHTML = '';
      }
    }

    const popElAlign = $('companySwitchPopover');
    if (popElAlign && !popElAlign.hidden) {
      const rect = switchEl.getBoundingClientRect();
      popElAlign.classList.toggle('align-right', rect.left + 585 > window.innerWidth - 12);
    }

    const coHeadEl = $('companySwitchCoHead');
    if (coHeadEl) {
      coHeadEl.textContent = q
        ? `Matching Companies (${visibleBtnCount})`
        : (indFilter === 'all'
          ? `Operating Companies (${allowedNames.length} Permitted)`
          : `${indFilter} (${(allowedIndGroups.find(g => g.id === indFilter) || { permittedCos: [] }).permittedCos.length} Permitted)`);
    }
    const footEl = $('companySwitchFootStatus');
    if (footEl) {
      footEl.textContent = q
        ? `Showing ${visibleBtnCount} match${visibleBtnCount === 1 ? '' : 'es'} · Press Enter to select`
        : `Active: ${trigInd} · ${trigCo} (${allowedIndCount} ${allowedIndCount === 1 ? 'Industry' : 'Industries'} · ${allowedNames.length} ${allowedNames.length === 1 ? 'Company' : 'Companies'} RLS)`;
    }
    const demoBtn = $('companySwitchScalePreviewBtn');
    if (demoBtn) {
      const isDemoSession = Boolean(STATE.demoVisitor || IS_DEMO || PARAMS.get('demo') === '1' || PARAMS.get('autologin') === '1' || PARAMS.get('scale') === '1' || STATE.enterpriseScalePreview);
      demoBtn.hidden = !(isOwner(user) && isDemoSession);
      demoBtn.classList.toggle('active', !!STATE.enterpriseScalePreview);
      demoBtn.innerHTML = STATE.enterpriseScalePreview
        ? `${ic('check_circle')} 10 Ind × 150 Co Preview (Reset to 14)`
        : `${ic('bolt')} Preview 10 Ind × 150 Co`;
    }
    const offBtn = $('officialScopeToggleBtn');
    if (offBtn) {
      const showOffToggle = isOwner(user) && !STATE.demoVisitor && getUserBookScope(user) !== 'official';
      const offOn = isOfficialScopeActive(user);
      offBtn.hidden = !showOffToggle;
      offBtn.classList.toggle('active', offOn);
      offBtn.innerHTML = offOn ? `${ic('shield')} Official Books (11% VAT)` : `${ic('shield')} All Books`;
    }
  }

  function wireCompanySwitch() {
    const switchEl = $('companySwitch');
    if (!switchEl || switchEl.dataset.pickerWired === '1') return;
    switchEl.dataset.pickerWired = '1';
    const trigBtn = $('companySwitchTrigger');
    const popEl = $('companySwitchPopover');
    const searchEl = $('companySwitchSearch');
    const allBtn = $('companySwitchSelectAllBtn');
    const demoBtn = $('companySwitchScalePreviewBtn');
    const offBtn = $('officialScopeToggleBtn');
    const doneBtn = $('companySwitchDoneBtn');

    const setOpen = (open) => {
      switchEl.classList.toggle('open', !!open);
      if (popEl) popEl.hidden = !open;
      if (trigBtn) trigBtn.setAttribute('aria-expanded', String(!!open));
      if (open) {
        syncCompanySwitchUi();
        if (searchEl) setTimeout(() => { try { searchEl.focus({ preventScroll: true }); } catch (_) {} }, 20);
      } else {
        if (searchEl && searchEl.value) {
          searchEl.value = '';
          syncCompanySwitchUi();
        }
        if (STATE.renderPending) renderApp();
      }
    };

    if (trigBtn) {
      trigBtn.addEventListener('click', e => {
        e.stopPropagation();
        const willOpen = popEl ? popEl.hidden : !switchEl.classList.contains('open');
        if (willOpen) {
          const clickedCoSeg = e.target && e.target.closest && e.target.closest('.ep-seg-co');
          const clickedIndSeg = e.target && e.target.closest && e.target.closest('.ep-seg-ind');
          if (clickedCoSeg) {
            STATE.companySwitchIndFilter = getActiveIndustry(STATE.company);
          } else if (clickedIndSeg) {
            STATE.companySwitchIndFilter = 'all';
          }
        }
        setOpen(willOpen);
      });
    }
    if (doneBtn) {
      doneBtn.addEventListener('click', e => {
        e.stopPropagation();
        setOpen(false);
      });
    }
    if (searchEl) {
      searchEl.addEventListener('input', () => {
        syncCompanySwitchUi();
      });
      searchEl.addEventListener('keydown', e => {
        const visibleBtns = Array.from(switchEl.querySelectorAll('.entity-btn:not([hidden])'));
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
          if (!visibleBtns.length) return;
          e.preventDefault();
          const curIdx = visibleBtns.findIndex(b => b.classList.contains('kbd-focus'));
          visibleBtns.forEach(b => b.classList.remove('kbd-focus'));
          const nextIdx = e.key === 'ArrowDown'
            ? (curIdx < visibleBtns.length - 1 ? curIdx + 1 : 0)
            : (curIdx > 0 ? curIdx - 1 : visibleBtns.length - 1);
          const targetBtn = visibleBtns[nextIdx];
          if (targetBtn) {
            targetBtn.classList.add('kbd-focus');
            try { targetBtn.scrollIntoView({ block: 'nearest' }); } catch (_) {}
          }
        } else if (e.key === 'Enter') {
          e.preventDefault();
          const focusedBtn = switchEl.querySelector('.entity-btn.kbd-focus:not([hidden])') || visibleBtns[0];
          if (focusedBtn) {
            selectCompanyScope(focusedBtn.getAttribute('data-company'), true);
          }
        } else if (e.key === 'Escape') {
          e.preventDefault();
          if (searchEl.value) {
            searchEl.value = '';
            syncCompanySwitchUi();
          } else {
            setOpen(false);
          }
        }
      });
    }
    if (allBtn) {
      allBtn.addEventListener('click', e => {
        e.stopPropagation();
        STATE.companySwitchIndFilter = 'all';
        if (searchEl) searchEl.value = '';
        const allowedCos = getAllowedCompanyKeys(activeUser());
        selectCompanyScope(allowedCos[0] || 'manufacturing-group', true);
      });
    }
    if (demoBtn) {
      demoBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (!isOwner() || !(STATE.demoVisitor || IS_DEMO || PARAMS.get('demo') === '1' || PARAMS.get('autologin') === '1' || PARAMS.get('scale') === '1' || STATE.enterpriseScalePreview)) return;
        STATE.enterpriseScalePreview = !STATE.enterpriseScalePreview;
        STATE.enterprisePreviewCompanies = STATE.enterpriseScalePreview ? buildEnterprisePreviewCatalog() : [];
        STATE.companySwitchIndFilter = 'all';
        applyUserRlsAndPermissions();
        if (STATE.view === 'users') {
          updateSeatEditorDom();
        }
        toast(STATE.enterpriseScalePreview
          ? '⚡ Enterprise Scale Preview active: 10 Industries × 15 Companies (150 Companies) loaded'
          : 'Restored live BHFIRMS multi-industry catalog (6 Industries · 14 Companies)');
      });
    }
    if (offBtn) {
      offBtn.addEventListener('click', e => {
        e.stopPropagation();
        if (!isOwner() || STATE.demoVisitor || getUserBookScope() === 'official') return;
        STATE.officialBookScope = !STATE.officialBookScope;
        STATE.shown = {};
        STATE.pbiTablePage = {};
        applyUserRlsAndPermissions();
        renderApp();
        toast(STATE.officialBookScope
          ? 'Official Books active: scoped strictly to 11% VAT-invoiced activity'
          : 'All Books active: showing complete operational ledger');
      });
    }
    switchEl.querySelectorAll('.entity-btn').forEach(btn => {
      btn.addEventListener('click', e => {
        e.stopPropagation();
        selectCompanyScope(btn.getAttribute('data-company'), true);
      });
    });
    document.addEventListener('mousedown', e => {
      if (switchEl.classList.contains('open') && (!e.target || !e.target.closest('#companySwitch'))) {
        setOpen(false);
      }
    });
    window.addEventListener('resize', () => {
      if (popEl && !popEl.hidden) {
        const rect = switchEl.getBoundingClientRect();
        popEl.classList.toggle('align-right', rect.left + 585 > window.innerWidth - 12);
      }
    });
  }

  function applyUserRlsAndPermissions() {
    const user = activeUser();
    if (STATE._lastRlsUserId !== String(user && user.id || '')) {
      STATE._lastRlsUserId = String(user && user.id || '');
      STATE.companySwitchIndFilter = 'all';
      const searchInp = $('companySwitchSearch');
      if (searchInp) searchInp.value = '';
    }
    const allowedCos = getAllowedCompanyKeys(user);
    const allowedNames = allowedCompanyNames(user);
    const catalog = getCompanyCatalog();
    STATE.allowedCompanyNames = allowedNames;
    STATE._officialScopeActive = isOfficialScopeActive(user);
    STATE._canSeeTaxBreakdown = canSeeTaxBreakdown(user);
    STATE.isOfficialRecord = isOfficialRecord;
    STATE.canAccessRdlReport = r => canAccessRdlReport(r, user);

    const isPermittedIndScope = String(STATE.company || '').startsWith('industry:') && allowedNames.some(n => {
      const hit = catalog.find(c => c.name.toLowerCase() === n.toLowerCase());
      return hit && hit.industry === String(STATE.company).slice(9);
    });
    if (!allowedCos.includes(STATE.company) && !isPermittedIndScope) STATE.company = allowedCos[0];
    const activeIndNow = getActiveIndustry(STATE.company);
    let compatViewNow = resolveIndustryCompatibleView(STATE.view, activeIndNow);
    if (!canViewView(compatViewNow, user)) {
      compatViewNow = resolveIndustryCompatibleView(defaultViewFor(user), activeIndNow);
    }
    if (compatViewNow !== STATE.view) {
      STATE.view = compatViewNow;
      STATE.search = '';
      STATE.chipFilter = 'all';
      STATE.shown = {};
      STATE._resetWorkspaceScroll = true;
      _preModalWorkspaceScrollSnap = null;
      _preModalWorkspaceScope = '';
      if (STATE.authed && VIEW_TITLES[STATE.view]) {
        const targetHash = '#' + STATE.view;
        if (location.hash !== targetHash) {
          try {
            history.replaceState({ view: STATE.view, company: STATE.company }, '', targetHash);
          } catch (_) {}
          if (location.hash !== targetHash) {
            try { location.hash = targetHash; } catch (__) {}
          }
        }
      }
    }
    syncIndustrySidebarDom(activeIndNow);
    syncCompanySwitchUi();

    const mfgAllowed = STATE.enterpriseScalePreview ? allowedNames : allowedNames.filter(n => !/^(bdeir\s*holding|blanca|la\s*una|palms|voile|platinum|korri\s*auto|shacman|properties|4235\s*company(\s*s\.?a\.?l\.?)?|insurance\s*company)$/i.test(n));
    const mfgCatLen = STATE.enterpriseScalePreview ? catalog.length : catalog.filter(c => !['bdeirholding', 'blanca', 'launa', 'palms', 'voile', 'platinum', 'korriauto', 'shacman', 'properties', '4235company', 'insurance'].includes(c.key)).length;
    COMPANY_LABELS['manufacturing-group'] = mfgAllowed.length >= mfgCatLen
      ? `All Manufacturing Group (${mfgAllowed.slice(0, 3).join(' · ')}${mfgAllowed.length > 3 ? ' +' + (mfgAllowed.length - 3) + ' more' : ''})`
      : `Assigned Entities (${mfgAllowed.slice(0, 3).join(' · ')}${mfgAllowed.length > 3 ? ' +' + (mfgAllowed.length - 3) + ' more' : ''})`;
    COMPANY_MOBILE_LABELS['manufacturing-group'] = mfgAllowed.length >= mfgCatLen
      ? `All Group (${mfgAllowed.length})`
      : `All Assigned (${mfgAllowed.length})`;

    document.querySelectorAll('#sidebarNav .nav-item').forEach(btn => {
      const hubId = btn.getAttribute('data-hub') || btn.getAttribute('data-view');
      btn.hidden = !canViewHub(hubId, user);
    });
    document.querySelectorAll('#sidebarNav .grp').forEach(grpEl => {
      let sib = grpEl.nextElementSibling, anyVisible = false;
      while (sib && !sib.classList.contains('grp')) {
        if (sib.classList.contains('nav-item') && !sib.hidden) { anyVisible = true; break; }
        sib = sib.nextElementSibling;
      }
      grpEl.hidden = !anyVisible;
    });
    const sysBar = $('railSystemBar');
    if (sysBar) {
      let anySysVisible = false;
      sysBar.querySelectorAll('button.rail-sys-btn[data-hub]').forEach(btn => {
        const hubId = btn.getAttribute('data-hub') || btn.getAttribute('data-view');
        const vis = canViewHub(hubId, user);
        btn.hidden = !vis;
        if (vis) anySysVisible = true;
      });
      sysBar.hidden = !anySysVisible;
    }
    if (!canViewView(STATE.view, user)) STATE.view = defaultViewFor(user);

    if (STATE.pbiPage && !canAccessPbiPage(STATE.pbiPage, user)) {
      STATE.pbiPage = 'p01_overview';
    }
    if (STATE.activeTableKey && !canAccessTable(STATE.activeTableKey, user)) {
      STATE.activeTableKey = 'sales_tickets';
    }
    if (window.MFG_RDL && Array.isArray(window.MFG_RDL.RDL_CATALOG)) {
      const permittedRdl = window.MFG_RDL.RDL_CATALOG.filter(r => canAccessRdlReport(r, user));
      if (permittedRdl.length && !permittedRdl.some(r => String(r.id || r.code) === String(STATE.activeStatement))) {
        STATE.activeStatement = permittedRdl[0].id || permittedRdl[0].code;
      }
    }

    const newBtn = $('newEntryBtn');
    if (newBtn) newBtn.hidden = !canEnterAny(user);
    const mNewBtn = $('mobileNewEntryBtn');
    if (mNewBtn) mNewBtn.hidden = !canEnterAny(user);

    const avEl = $('railUserAvatar'), nmEl = $('railUserName'), rlEl = $('activeRoleBadge'), scEl = $('railRlsScope');
    if (avEl) avEl.textContent = getInitials(user.full_name);
    if (nmEl) { nmEl.textContent = user.full_name; nmEl.setAttribute('data-full-text', user.full_name); nmEl.removeAttribute('title'); }
    if (rlEl) { rlEl.textContent = user.role; rlEl.setAttribute('data-full-text', user.role); rlEl.removeAttribute('title'); }
    if (scEl) {
      const shortNames = allowedNames.map(n => n.replace(/BBConstruction/g, 'BBC').replace(/Lions Transport/g, 'Lions'));
      const fullScope = allowedNames.join(' · ');
      scEl.textContent = shortNames.length <= 3
        ? shortNames.join(', ')
        : `${shortNames.slice(0, 2).join(', ')} +${shortNames.length - 2} more`;
      scEl.setAttribute('data-full-text', fullScope || scEl.textContent);
      scEl.removeAttribute('title');
    }
  }

  function resolveSelectedAuthUser() {
    if (FACE_STATE.pending2faUser || FACE_STATE.pendingPinUser) return null;
    const sel = norm(FACE_STATE.selectedAuthEmail || '');
    if (!sel) return null;
    return STATE.users.find(u => u.status !== 'Suspended' && norm(u.email) === sel) || null;
  }

  function syncAuthSelectedSeatUi() {
    const grp = $('authSelectedGroup');
    const bar = $('authSelectedSeatBar');
    const pinRow = $('authPinRow');
    const pinEl = $('authPinInput');
    const avEl = $('authSelectedSeatAvatar');
    const nmEl = $('authSelectedSeatName');
    const metaEl = $('authSelectedSeatMeta');
    const drawer = $('authSeatDrawer');
    const divEl = $('authMethodDivider');
    const divLblEl = $('authMethodDividerLabel');
    const selUser = resolveSelectedAuthUser();
    const waitingCam2FA = !!FACE_STATE.pending2faUser;
    const waitingPin2FA = !!FACE_STATE.pendingPinUser;
    const showPicker = !selUser && !waitingCam2FA && !waitingPin2FA;
    const showPinGroup = !!(selUser || waitingPin2FA);

    FACE_STATE.seatDrawerOpen = showPicker;

    if (drawer) {
      drawer.hidden = !showPicker;
    }
    if (grp) {
      grp.hidden = !showPinGroup;
    }
    if (bar) {
      if (selUser) {
        bar.hidden = false;
        if (avEl) avEl.textContent = getInitials(selUser.full_name);
        if (nmEl) nmEl.textContent = selUser.full_name;
        if (metaEl) metaEl.textContent = `${formatCleanSeatRole(selUser.role)} · ${formatSeatEntityCountLabel(selUser)}`;
      } else {
        bar.hidden = true;
      }
    }
    if (pinRow) {
      pinRow.hidden = !showPinGroup;
    }
    if (pinEl) {
      const targetUser = waitingPin2FA ? FACE_STATE.pendingPinUser : selUser;
      if (targetUser) {
        const firstName = String(targetUser.full_name || '').trim().split(/\s+/)[0] || 'account';
        pinEl.setAttribute('placeholder', `Enter PIN for ${firstName}`);
        pinEl.setAttribute('aria-label', `Access PIN for ${targetUser.full_name}`);
      } else {
        pinEl.setAttribute('placeholder', 'Access PIN');
        pinEl.setAttribute('aria-label', 'Access PIN');
      }
    }
    if (divEl) {
      const wsMode = getWorkspaceAuthMode();
      if (waitingCam2FA || waitingPin2FA || wsMode === 'pin_only') {
        divEl.hidden = true;
      } else {
        divEl.hidden = false;
        if (divLblEl) {
          divLblEl.textContent = showPicker
            ? (IS_DEMO ? 'or open a demo workspace' : 'or select account for PIN')
            : 'or sign in with PIN';
        }
      }
    }
  }

  function setAuthSeatDrawerOpen(open, opts = {}) {
    if (open) {
      FACE_STATE.selectedAuthEmail = '';
    }
    FACE_STATE.seatDrawerOpen = !!open;
    if (!open) FACE_STATE.disambiguatePin = '';
    const emEl = $('authEmailInput');
    const pinEl = $('authPinInput');
    if (emEl) {
      emEl.value = '';
    }
    renderQuickSeatsInAuthGate();
    syncAuthSelectedSeatUi();
    if (!opts.silentFocus && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
      if (open && emEl && !coarse) {
        setTimeout(() => { try { emEl.focus({ preventScroll: true }); } catch (_) {} }, 30);
      } else if (!open && pinEl && !coarse) {
        setTimeout(() => { try { pinEl.focus({ preventScroll: true }); } catch (_) {} }, 30);
      }
    }
  }

  function renderQuickSeatsInAuthGate() {
    const listEl = $('quickSeatList');
    if (!listEl) return;
    const emEl = $('authEmailInput');
    const rawFilter = (!resolveSelectedAuthUser() && emEl) ? norm(emEl.value) : '';
    const disPin = String(FACE_STATE.disambiguatePin || '').trim();
    const sessFreq = new Map();
    (STATE.sessions || []).forEach(s => {
      if (!s) return;
      const ek = norm(s.email || s.user_email || '');
      const nk = norm(s.user_name || s.full_name || '');
      if (ek) sessFreq.set(ek, (sessFreq.get(ek) || 0) + 1);
      if (nk) sessFreq.set(nk, (sessFreq.get(nk) || 0) + 1);
    });
    const activeSeats = STATE.users.filter(u => u.status !== 'Suspended').slice().sort((a, b) => {
      const fa = (sessFreq.get(norm(a.email)) || 0) + (sessFreq.get(norm(a.full_name)) || 0);
      const fb = (sessFreq.get(norm(b.email)) || 0) + (sessFreq.get(norm(b.full_name)) || 0);
      return fb - fa;
    });
    const filtered = activeSeats.filter(u => {
      if (disPin && String(u.pin_code || '1111').trim() !== disPin) return false;
      if (!rawFilter) return true;
      return norm(u.full_name).includes(rawFilter) || norm(u.email).includes(rawFilter) || norm(u.role).includes(rawFilter);
    });

    if (!filtered.length) {
      listEl.innerHTML = `<div class="quick-seat-empty">No matching team account</div>`;
      return;
    }

    listEl.innerHTML = filtered.map(u => {
      const active = norm(FACE_STATE.selectedAuthEmail || '') === norm(u.email);
      const seatMode = effectiveSeatAuthMode(u);
      const rightTag = IS_DEMO
        ? `<span class="quick-seat-demo-tag">Open</span>`
        : (seatMode === 'face_only'
          ? `<span class="quick-seat-cue">Face ID</span>`
          : `<span class="quick-seat-cue">PIN <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg></span>`);
      return `
      <button type="button" class="quick-seat-item${active ? ' is-selected' : ''}" data-quick-seat="${esc(u.email)}">
        <span class="quick-seat-av" aria-hidden="true" data-no-i18n="1">${esc(getInitials(u.full_name))}</span>
        <div class="quick-seat-copy">
          <b data-no-i18n="1">${esc(u.full_name)}</b>
          <small>${esc(formatCleanSeatRole(u.role))} · ${esc(formatSeatEntityCountLabel(u))}</small>
        </div>
        ${rightTag}
      </button>
    `;
    }).join('');

    listEl.querySelectorAll('[data-quick-seat]').forEach(btn => {
      btn.addEventListener('click', () => {
        const u = STATE.users.find(x => norm(x.email) === norm(btn.getAttribute('data-quick-seat')));
        if (!u) return;
        const pinEl = $('authPinInput');
        if (IS_DEMO) {
          FACE_STATE.selectedAuthEmail = u.email;
          if (pinEl) pinEl.value = u.pin_code || '1111';
          performLogin(u.email, u.pin_code || '1111', { bypass2FA: true });
          return;
        }
        if (effectiveSeatAuthMode(u) === 'face_only') {
          authError(`${u.full_name} uses Face ID only. Look at the camera above.`, { noShake: true, keepPin: true });
          setAuthHint(`Look at camera to sign in as ${u.full_name}`, 'warn');
          if (!FACE_STATE.camActive && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) startAuthFaceScanner(true);
          return;
        }
        const pendingDisPin = String(FACE_STATE.disambiguatePin || '').trim();
        FACE_STATE.selectedAuthEmail = u.email;
        FACE_STATE.disambiguatePin = '';
        FACE_STATE.seatDrawerOpen = false;
        if (emEl) emEl.value = '';
        const errEl = $('authErrorBox');
        if (errEl) errEl.hidden = true;
        syncAuthSelectedSeatUi();
        if (pendingDisPin && pendingDisPin === String(u.pin_code || '1111').trim()) {
          performLogin(u.email, pendingDisPin);
          return;
        }
        if (pinEl) {
          pinEl.value = '';
          try { pinEl.focus({ preventScroll: true }); } catch (_) {}
        }
      });
    });
  }

  function openAuthGate(prefillEmail) {
    if (window.MFG_ASK && typeof window.MFG_ASK.clearSessionState === 'function') {
      window.MFG_ASK.clearSessionState();
    }
    if (window.MFG_STEP_UP && typeof window.MFG_STEP_UP.clearLease === 'function') {
      window.MFG_STEP_UP.clearLease();
    }
    STATE.authed = false;
    window.__mfgSwResuming = false;
    document.documentElement.classList.remove('sw-resuming');
    FACE_STATE.pending2faUser = null;
    FACE_STATE.pendingPinUser = null;
    FACE_STATE.streakUser = null;
    FACE_STATE.streakCount = 0;
    FACE_STATE.edgeProbeStreak = 0;
    FACE_STATE.edgeProbeCooldownUntil = 0;
    FACE_STATE.edgeProbeBusy = false;
    FACE_STATE.disambiguatePin = '';
    setAuthStreak(0, 3);
    if (hasServerApi() && !isDemoSandboxSession() && !_usersApiHydratedOnce) {
      hydrateServerUsersOnce();
    }
    let candidateEmail = prefillEmail || '';
    if (!candidateEmail && !IS_DEMO && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      try { candidateEmail = localStorage.getItem('isabi_mfg_last_seat') || ''; } catch (_) {}
    }
    const preUser = candidateEmail ? STATE.users.find(u => u.status !== 'Suspended' && norm(u.email) === norm(candidateEmail)) : null;
    FACE_STATE.selectedAuthEmail = preUser ? preUser.email : '';
    FACE_STATE.seatDrawerOpen = !preUser;
    resetLivenessState();
    window.__mfgAuthedEmail = '';
    const emEl = $('authEmailInput');
    const pinEl = $('authPinInput');
    if (emEl) emEl.value = '';
    if (pinEl) pinEl.value = '';
    const errEl = $('authErrorBox');
    if (errEl) errEl.hidden = true;
    renderQuickSeatsInAuthGate();
    updateCloudBadges();
    updateAuthFaceUi();
    syncAuthSelectedSeatUi();
    const gate = $('authGate');
    if (gate) gate.hidden = false;
    document.body.classList.add('locked');
    if (!FACE_STATE.authCamStoppedByUser) startAuthFaceScanner(false);
    setTimeout(() => {
      if (!STATE.authed && preUser && pinEl) {
        const coarse = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
        if (!coarse && window.innerWidth > 860) {
          try { pinEl.focus({ preventScroll: true }); } catch (_) {}
        }
      }
    }, 60);
  }

  function closeAuthGate() {
    STATE.authed = true;
    window.__mfgSwResuming = false;
    document.documentElement.classList.remove('sw-resuming');
    if (FACE_STATE.loopTimer) { clearTimeout(FACE_STATE.loopTimer); FACE_STATE.loopTimer = null; }
    FACE_STATE.camActive = false;
    FACE_STATE.pending2faUser = null;
    FACE_STATE.pendingPinUser = null;
    FACE_STATE.streakUser = null;
    FACE_STATE.streakCount = 0;
    FACE_STATE.edgeProbeStreak = 0;
    FACE_STATE.edgeProbeCooldownUntil = 0;
    FACE_STATE.edgeProbeBusy = false;
    FACE_STATE.seatDrawerOpen = false;
    FACE_STATE.disambiguatePin = '';
    FACE_STATE.enrolCamActive = false;
    window.__mfgAuthedEmail = activeUser().email;
    const gate = $('authGate');
    if (gate) gate.hidden = true;
    document.body.classList.remove('locked');
    setAuthStreak(0, 3);
    resetLivenessState();
    const shouldKeepNonAuthCam = () => Boolean(
      FACE_STATE.enrolCamActive ||
      KIOSK_ATT_STATE.camActive ||
      KIOSK_ATT_STATE.camStarting ||
      KIOSK_ADMIN_MODAL_STATE.camActive ||
      STAFF_FACE_MODAL_STATE.camActive ||
      (STATE.view === 'kiosks' && STATE.activeKiosk === 'attendance' && STATE.kioskLocked)
    );
    if (IS_AUTOMATED_TEST) {
      if (!shouldKeepNonAuthCam()) stopFaceCamera();
      updateAuthFaceUi();
    } else if (typeof requestAnimationFrame === 'function') {
      requestAnimationFrame(() => {
        setTimeout(() => {
          if (STATE.authed && !shouldKeepNonAuthCam()) {
            stopFaceCamera();
            updateAuthFaceUi();
          }
        }, 0);
      });
    } else {
      if (!shouldKeepNonAuthCam()) stopFaceCamera();
      updateAuthFaceUi();
    }
    const keep = new URLSearchParams();
    ['demo', 'nosse'].forEach(p => { if (PARAMS.has(p)) keep.set(p, PARAMS.get(p)); });
    if (STATE.kioskLocked && STATE.view === 'kiosks' && STATE.activeKiosk) {
      keep.set('kiosk', STATE.activeKiosk);
    }
    const targetUrl = location.pathname + (keep.toString() ? '?' + keep.toString() : '') + (VIEW_TITLES[STATE.view] ? '#' + STATE.view : '');
    if (location.pathname + location.search + location.hash !== targetUrl) {
      history.replaceState({ view: STATE.view }, '', targetUrl);
    }
  }

  function signOut() {
    if (isDemoSandboxSession()) {
      try {
        for (let i = sessionStorage.length - 1; i >= 0; i--) {
          const k = sessionStorage.key(i);
          if (k && k.startsWith('demo_sbx_')) sessionStorage.removeItem(k);
        }
        sessionStorage.removeItem('isabi_mfg_sw_resume');
      } catch (_) {}
    } else {
      if (hasServerApi()) {
        try { edgeApiFetch('./api/auth/logout', { method: 'POST' }).catch(() => {}); } catch (_) {}
      }
      setEdgeSessionToken('');
      try { localStorage.removeItem('isabi_mfg_active_email'); } catch (_) {}
      try { localStorage.removeItem('isabi_mfg_last_seat'); } catch (_) {}
      try { localStorage.removeItem('isabi_mfg_kiosk_station_seat'); } catch (_) {}
      try { sessionStorage.removeItem('isabi_mfg_sw_resume'); } catch (_) {}
    }
    clearTimeout(toastTimer);
    clearTimeout(toastFadeTimer);
    const tEl = $('toast');
    if (tEl) { tEl.classList.remove('is-leaving'); tEl.hidden = true; }
    closeEntryModal(true);
    if (window.MFG_ASK && typeof window.MFG_ASK.clearSessionState === 'function') {
      window.MFG_ASK.clearSessionState();
    }
    if (window.MFG_STEP_UP && typeof window.MFG_STEP_UP.clearLease === 'function') {
      window.MFG_STEP_UP.clearLease();
    }
    if (window.MFG_TELEMATICS && typeof window.MFG_TELEMATICS.clearSessionCache === 'function') {
      window.MFG_TELEMATICS.clearSessionCache();
    }
    const keep = new URLSearchParams();
    ['demo', 'nosse'].forEach(p => { if (PARAMS.has(p)) keep.set(p, PARAMS.get(p)); });
    history.replaceState({ view: STATE.view }, '', location.pathname + (keep.toString() ? '?' + keep.toString() : ''));
    openAuthGate('');
  }

  function authError(msg, opts = {}) {
    const errEl = $('authErrorBox');
    if (errEl) { errEl.textContent = msg; errEl.hidden = false; }
    const card = document.querySelector('.auth-card');
    if (card && !opts.noShake) { card.classList.remove('shake'); void card.offsetWidth; card.classList.add('shake'); }
    const pinEl = $('authPinInput');
    if (pinEl && !opts.keepPin) {
      pinEl.value = '';
      try { pinEl.focus({ preventScroll: true }); } catch (_) {}
    }
  }

  let loginAttempts = 0;
  let loginLockUntil = 0;
  let authUiLoginBusy = false;
  let authPinProbeTimer = null;
  let authPinProbeInFlight = false;
  async function performLogin(emailRaw, pinRaw, opts = {}) {
    let email = norm(emailRaw);
    const pin = String(pinRaw || '').trim();
    const silentProbe = Boolean(opts && opts.silentAutoProbe);
    if (Date.now() < loginLockUntil) {
      if (!silentProbe) authError(`Too many attempts. Wait ${Math.ceil((loginLockUntil - Date.now()) / 1000)}s.`);
      return false;
    }
    let serverVerifiedLogin = Boolean(opts && opts.serverToken);
    if (!email && pin) {
      const matches = STATE.users.filter(u => u.status !== 'Suspended' && u.pin_code && String(u.pin_code).trim() === pin);
      if (matches.length === 1) {
        email = norm(matches[0].email);
        const emEl = $('authEmailInput');
        if (emEl && !FACE_STATE.seatDrawerOpen) emEl.value = matches[0].email;
      } else if (matches.length > 1) {
        FACE_STATE.disambiguatePin = pin;
        setAuthSeatDrawerOpen(true, { silentFocus: true });
        authError('Select your account below to finish signing in.', { keepPin: true, noShake: true });
        return false;
      } else if (hasServerApi() && !isDemoSandboxSession()) {
        try {
          const rPin = await edgeApiFetch('./api/auth/login', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ pin, method: opts.method || 'PIN', device: 'PIN Lookup' })
          });
          const jPin = rPin ? await rPin.json().catch(() => null) : null;
          if (rPin && rPin.status === 409 && jPin && jPin.ambiguous) {
            FACE_STATE.disambiguatePin = pin;
            setAuthSeatDrawerOpen(true, { silentFocus: true });
            authError('Select your account below to finish signing in.', { keepPin: true, noShake: true });
            return false;
          }
          if (jPin && jPin.two_factor_face_required && jPin.email) {
            email = norm(jPin.email);
            const uIdx = STATE.users.findIndex(u => norm(u.email) === email);
            if (uIdx >= 0) { STATE.users[uIdx].pin_code = pin; STATE.users[uIdx]._verifiedPin = true; delete STATE.users[uIdx].pin_redacted; }
          } else if (rPin && rPin.ok && jPin && jPin.user && jPin.user.email) {
            email = norm(jPin.user.email);
            if (jPin.token) setEdgeSessionToken(jPin.token);
            const uIdx = STATE.users.findIndex(u => norm(u.email) === email);
            if (uIdx >= 0) STATE.users[uIdx] = mergeUserRow(STATE.users[uIdx], Object.assign({}, jPin.user, { pin_code: pin, _verifiedPin: true }));
            else STATE.users.push(ensureCanonicalMultiIndustrySeat(Object.assign({}, jPin.user, { pin_code: pin, _verifiedPin: true })));
            serverVerifiedLogin = true;
          } else {
            if (silentProbe) return false;
            if (rPin && rPin.status === 429) {
              loginLockUntil = Date.now() + 30000;
              authError((jPin && jPin.error) || 'Too many failed sign-in attempts. Wait 30 seconds.');
              return false;
            }
            loginAttempts += 1;
            if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
            else authError('Incorrect Access PIN.');
            return false;
          }
        } catch (_) {
          if (silentProbe) return false;
          loginAttempts += 1;
          if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
          else authError('Incorrect Access PIN.');
          return false;
        }
      } else {
        if (silentProbe) return false;
        loginAttempts += 1;
        if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
        else authError('Incorrect Access PIN.');
        return false;
      }
    }
    const reqMethod = String((opts && opts.method) || '');
    const isPinlessBypass = Boolean(opts && opts.bypass2FA) && (
      (/^face\s*id/i.test(reqMethod) && !/face\s*id\s*\+\s*pin/i.test(reqMethod)) ||
      reqMethod === 'Owner Impersonation' ||
      reqMethod === 'Interactive Sandbox'
    );
    if (!email) { if (!silentProbe) authError('Enter your Access PIN.'); return false; }
    if (!pin && !isPinlessBypass && !serverVerifiedLogin) { if (!silentProbe) authError('Enter your Access PIN.'); return false; }

    let idx = STATE.users.findIndex(u => norm(u.email) === email);
    if (idx < 0 && !email.includes('@')) {
      const subMatches = STATE.users.filter(u => u.status !== 'Suspended' && (norm(u.full_name).includes(email) || norm(u.email).includes(email)));
      if (subMatches.length === 1) idx = STATE.users.indexOf(subMatches[0]);
    }
    if (idx < 0) { if (!silentProbe) authError('Account not found in this workspace.'); return false; }
    const user = STATE.users[idx];
    if (user.status === 'Suspended') { if (!silentProbe) authError('This seat is suspended. Contact an administrator.'); return false; }
    const localPinStr = String(user.pin_code || '').trim();
    const completedFaceFirst2FA = !!(FACE_STATE.pendingPinUser && norm(FACE_STATE.pendingPinUser.email) === norm(user.email));
    const pendingFaceVecForPin = completedFaceFirst2FA
      ? (opts.faceDescriptor || FACE_STATE.pendingPinDescriptor || FACE_STATE.lastVerifiedDescriptor || null)
      : null;
    if (!serverVerifiedLogin && !isPinlessBypass && (!localPinStr || pin !== localPinStr)) {
      let verifiedViaApi = false;
      let rateLimitedErr = '';
      if (hasServerApi() && !isDemoSandboxSession()) {
        try {
          const checkFaceVec = pendingFaceVecForPin || opts.faceDescriptor;
          const rCheck = await edgeApiFetch('./api/auth/login', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              email: user.email,
              pin,
              method: completedFaceFirst2FA ? (opts.method || 'Face ID + PIN 2FA') : (opts.method || 'PIN'),
              face_descriptor: Array.isArray(checkFaceVec) && checkFaceVec.length === 128 ? checkFaceVec : undefined,
              device: 'PIN Verify'
            })
          });
          const jCheck = rCheck ? await rCheck.json().catch(() => null) : null;
          if (rCheck && rCheck.ok && jCheck && jCheck.ok) {
            if (jCheck.token) setEdgeSessionToken(jCheck.token);
            if (jCheck.user) STATE.users[idx] = mergeUserRow(user, Object.assign({}, jCheck.user, { pin_code: pin, _verifiedPin: true }));
            user.pin_code = pin;
            user._verifiedPin = true;
            delete user.pin_redacted;
            verifiedViaApi = true;
            serverVerifiedLogin = true;
          } else if (jCheck && jCheck.two_factor_face_required) {
            user.pin_code = pin;
            user._verifiedPin = true;
            delete user.pin_redacted;
            verifiedViaApi = true;
          } else if (rCheck && rCheck.status === 429) {
            rateLimitedErr = (jCheck && jCheck.error) || 'Too many failed sign-in attempts. Wait 60 seconds.';
          }
        } catch (_) {}
      }
      const demoFallbackPin = String((DEFAULT_USERS.find(du => norm(du.email) === norm(user.email)) || {}).pin_code || '1111').trim();
      if (!verifiedViaApi && (!localPinStr ? (Boolean(window.ISABI_HAS_EDGE_API || window.__ISABI_TEST_EDGE) && !isDemoSandboxSession() ? true : (pin !== demoFallbackPin && pin !== '1111')) : true)) {
        if (silentProbe) return false;
        if (rateLimitedErr) {
          loginLockUntil = Date.now() + 30000;
          authError(rateLimitedErr);
          return false;
        }
        loginAttempts += 1;
        if (loginAttempts >= 5) { loginLockUntil = Date.now() + 30000; loginAttempts = 0; authError('Too many wrong PINs. Locked for 30 seconds.'); }
        else authError('Incorrect PIN for ' + user.full_name + '.');
        return false;
      }
    }
    loginAttempts = 0;

    const seatMode = effectiveSeatAuthMode(user);
    // If seat is configured for Face ID Only, block PIN-only sign-in and prompt for live camera scan
    if (!opts.bypass2FA && seatMode === 'face_only') {
      authError(`${user.full_name} requires Face ID to sign in. Look at the camera above.`);
      setAuthHint(`Look at the camera to sign in as ${user.full_name}`, 'warn');
      if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
      return 'face_only_required';
    }

    // If user already completed Live Face ID Step 1 under 'both' mode, completing PIN Step 2 signs them in!
    if (completedFaceFirst2FA) {
      FACE_STATE.pendingPinUser = null;
      FACE_STATE.pendingPinDescriptor = null;
      opts = Object.assign({}, opts, { bypass2FA: true, method: opts.method || 'Face ID + PIN 2FA', faceDescriptor: pendingFaceVecForPin || opts.faceDescriptor });
    }

    // Step-Up 2FA Biometric Gate: if this seat has enrolled Face ID and 2FA ('both') is enforced, require Live Face ID confirmation!
    if (!opts.bypass2FA && userRequiresFace2FA(user)) {
      FACE_STATE.pending2faUser = user;
      FACE_STATE.pendingPinUser = null;
      FACE_STATE.streakUser = null;
      FACE_STATE.streakCount = 0;
      FACE_STATE.edgeProbeStreak = 0;
      FACE_STATE.edgeProbeCooldownUntil = 0;
      FACE_STATE.edgeProbeBusy = false;
      resetLivenessState();
      const errEl = $('authErrorBox');
      if (errEl) errEl.hidden = true;
      updateAuthFaceUi();
      setAuthHint(`PIN verified. Look at the camera to verify ${user.full_name}.`, 'ok');
      if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
      return '2fa_pending';
    }

    const nowStr = nowStamp();
    const ua = navigator.userAgent || '';
    const devLabel = /iPhone|iPad/i.test(ua) ? 'iOS Safari' : (/Android/i.test(ua) ? 'Android Chrome' : (/Edg\//.test(ua) ? 'Desktop Edge' : 'Desktop Browser'));
    const standalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone;
    const authMethod = opts.method || 'PIN';
    const authConf = opts.confidence != null ? Number(opts.confidence) : null;
    const isEdgeAuthActive = Boolean(window.ISABI_HAS_EDGE_API || window.__ISABI_TEST_EDGE);

    if (hasServerApi() && !serverVerifiedLogin && !isDemoSandboxSession()) {
      const loginFaceVec = (Array.isArray(opts.faceDescriptor) && opts.faceDescriptor.length === 128)
        ? opts.faceDescriptor
        : ((opts.bypass2FA && Array.isArray(user.face_samples) && Array.isArray(user.face_samples[0]) && user.face_samples[0].length === 128)
          ? user.face_samples[0]
          : (Array.isArray(FACE_STATE.lastVerifiedDescriptor) && FACE_STATE.lastVerifiedDescriptor.length === 128 ? FACE_STATE.lastVerifiedDescriptor : undefined));
      try {
        const rLogin = await edgeApiFetch('./api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email: user.email, pin, device: devLabel, method: authMethod, confidence: authConf, face_descriptor: loginFaceVec })
        });
        if (rLogin && rLogin.ok) {
          const jLogin = await rLogin.json().catch(() => null);
          if (jLogin && jLogin.token) setEdgeSessionToken(jLogin.token);
          else setEdgeSessionToken('');
          const verifiedPinPatch = (pin && !isPinlessBypass) ? { pin_code: pin, _verifiedPin: true } : {};
          if (jLogin && jLogin.user) STATE.users[idx] = mergeUserRow(STATE.users[idx], Object.assign({}, jLogin.user, verifiedPinPatch));
          else if (pin && !isPinlessBypass) { STATE.users[idx].pin_code = pin; STATE.users[idx]._verifiedPin = true; delete STATE.users[idx].pin_redacted; }
        } else if (isEdgeAuthActive) {
          const jErr = rLogin ? await rLogin.json().catch(() => null) : null;
          if (jErr && jErr.two_factor_face_required) {
            FACE_STATE.pending2faUser = user;
            FACE_STATE.pendingPinUser = null;
            resetLivenessState();
            updateAuthFaceUi();
            setAuthHint(`PIN verified. Look at the camera to verify ${user.full_name}.`, 'ok');
            if (!FACE_STATE.camActive && !navigator.webdriver) startAuthFaceScanner(true);
            return '2fa_pending';
          }
          if (jErr && jErr.two_factor_pin_required) {
            FACE_STATE.pendingPinUser = user;
            FACE_STATE.pendingPinDescriptor = loginFaceVec || null;
            updateAuthFaceUi();
            setAuthHint(`Face verified for ${user.full_name}. Enter PIN to finish sign-in.`, 'ok');
            return '2fa_pin_pending';
          }
          authError((jErr && jErr.error) || ('Verification failed for ' + user.full_name + '.'));
          return false;
        } else {
          setEdgeSessionToken('');
        }
      } catch (_) {
        if (isEdgeAuthActive) {
          const canOfflineVerify = (localPinStr && pin === localPinStr) || (Array.isArray(loginFaceVec) && loginFaceVec.length === 128 && userFaceSamples(user).length > 0);
          if (!canOfflineVerify) {
            authError('Offline: cannot verify uncached seat credentials.');
            return false;
          }
        }
      }
    }

    FACE_STATE.pending2faUser = null;
    FACE_STATE.pendingPinUser = null;
    if (window.MFG_ASK && typeof window.MFG_ASK.clearSessionState === 'function' && STATE.activeUserIdx !== idx) {
      window.MFG_ASK.clearSessionState();
    }
    user.last_login_at = nowStr.slice(0, 16);
    STATE.activeUserIdx = idx;
    if (!isDemoSandboxSession()) {
      try { localStorage.removeItem('isabi_mfg_active_email'); } catch (_) {}
    }
    if (!IS_DEMO && !isDemoSandboxSession() && !navigator.webdriver && !window.__MFG_HEADLESS_TEST) {
      try { localStorage.setItem('isabi_mfg_last_seat', user.email); } catch (_) {}
      if (STATE.kioskLocked || STATE.view === 'kiosks') {
        try { localStorage.setItem('isabi_mfg_kiosk_station_seat', JSON.stringify({ email: user.email, ts: Date.now() })); } catch (_) {}
      }
    }
    STATE.sessions.unshift({
      id: uid('sess'),
      full_name: user.full_name,
      email: user.email,
      role: user.role,
      companies: user.companies,
      device: devLabel + (standalone ? ' · Home Screen app' : ''),
      method: authMethod,
      confidence: authConf,
      logged_in_at: nowStr
    });
    STATE.sessions = STATE.sessions.slice(0, 50);
    saveLocalAuthAndRecords();

    if (!getAllowedCompanyKeys(user).includes(STATE.company)) STATE.company = getAllowedCompanyKeys(user)[0];
    if (!canViewView(STATE.view, user)) STATE.view = defaultViewFor(user);
    closeAuthGate();
    STATE.search = '';
    STATE.showAddUserForm = false;
    renderApp();
    toastWelcome(user, authMethod);
    syncWithCloud(true);
    return true;
  }

  // ==========================================================================
  // ASK ISABI COPILOT BRIDGE (DELEGATES TO js/ask_isabi.js HYBRID ENGINE)
  // ==========================================================================
  function answerAskIsabi(qRaw) {
    if (window.MFG_ASK && typeof window.MFG_ASK.answer === 'function') {
      return window.MFG_ASK.answer(qRaw);
    }
    const k = getKPI();
    const scope = `${String(COMPANY_LABELS[STATE.company] || 'Selected Entities').split('(')[0].trim()} · ${k.label || 'All-Time'}`;
    return `<strong>${esc(scope)} Summary:</strong><br>Sales ${fmtUSD(k.sales_ttc, 2)} across ${fmtNum(k.loads)} loads · Gross Margin ${fmtUSD(k.gross_margin, 0)} · Operating Profit ${fmtUSD(k.operating_profit, 0)}.`;
  }

